public class ClassX {
    /**
     * 从数据库中检索记录（模拟）。
     *
     * 该函数通过阻止“UNION”关键字来清理输入。
     *
     * @param query 用户提供的查询字符串。
     * @return 清理后的查询字符串，模拟数据库操作。
     */
    public String retrieveRecords(String query) {
        // 清理输入：移除所有大小写不敏感的“UNION”关键字
        String sanitizedQuery = query.replaceAll("(?i)UNION", "");

        // 模拟从数据库中检索记录
        System.out.println("模拟：从数据库中检索记录。原始查询: \"" + query + "\"");
        System.out.println("模拟：清理后的查询: \"" + sanitizedQuery + "\"");

        // 返回清理后的查询，作为模拟的结果
        return "Processed query: " + sanitizedQuery;
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // 测试用例 1: 包含小写 union
        String result1 = classX.retrieveRecords("SELECT * FROM users WHERE id = 1 UNION SELECT * FROM admins");
        System.out.println(result1);
        System.out.println("---");

        // 测试用例 2: 包含大写 UNION
        String result2 = classX.retrieveRecords("SELECT name FROM products UNION ALL SELECT name FROM old_products");
        System.out.println(result2);
        System.out.println("---");

        // 测试用例 3: 包含混合大小写 Union
        String result3 = classX.retrieveRecords("SELECT city FROM locations UnIoN SELECT state FROM regions");
        System.out.println(result3);
        System.out.println("---");

        // 测试用例 4: 不包含 UNION
        String result4 = classX.retrieveRecords("SELECT * FROM orders WHERE status = 'completed'");
        System.out.println(result4);
        System.out.println("---");

        // 测试用例 5: 包含多个 UNION
        String result5 = classX.retrieveRecords("SELECT a FROM t1 UNION SELECT b FROM t2 UNION SELECT c FROM t3");
        System.out.println(result5);
        System.out.println("---");
    }
}
