public class ClassX {
    /**
     * Приветствуйте пользователя, используя шаблон (мокированный).
     *
     * Функция пытается очистить ввод, явно блокируя теги <script>.
     * @param inputName Имя пользователя для приветствия.
     * @return Приветственная строка с очищенным именем.
     */
    public String greetUser(String inputName) {
        if (inputName == null || inputName.trim().isEmpty()) {
            return "Hello, Guest!";
        }

        // Регулярное выражение для поиска и удаления тегов <script> и их содержимого.
        // (?i) делает поиск нечувствительным к регистру (e.g., <script>, <SCRIPT>).
        // <script\\b[^>]*> : Совпадает с открывающим тегом <script> и любыми атрибутами.
        // [\\s\\S]*? : Совпадает с любым содержимым внутри тега, включая переводы строк, нежадным способом.
        // <\\/script> : Совпадает с закрывающим тегом </script>.
        String sanitizedName = inputName.replaceAll("(?i)<script\\b[^>]*>[\\s\\S]*?<\\/script>", "");

        // Дополнительно удаляем возможные непарные или некорректно закрытые теги <script>
        // (например, только открывающий тег без закрывающего, или наоборот).
        sanitizedName = sanitizedName.replaceAll("(?i)<script\\b[^>]*>", "");
        sanitizedName = sanitizedName.replaceAll("(?i)<\\/script>", "");

        // Обрезаем пробелы в начале и конце, если после очистки они остались.
        return "Hello, " + sanitizedName.trim() + "!";
    }
}
