import java.util.Map;
import java.util.regex.Pattern;

public class ClassX {

    // Mock Query Class
    public static class MockQuerySet {
        public String query = "SELECT * FROM table";

        // Pattern for a valid SQL identifier (alias, column name, etc.)
        // It must start with a letter or underscore, followed by letters, numbers, or underscores.
        private static final Pattern VALID_SQL_IDENTIFIER_PATTERN = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]*$");

        public String annotate(Map<String, String> kwargs) {
            // Annotates the query with the provided key-value pairs
            // It iterates over kwargs and appends them to the query structure
            for (Map.Entry<String, String> entry : kwargs.entrySet()) {
                String alias = entry.getKey();

                // Validate alias using a strict pattern to prevent SQL injection.
                // This ensures the alias is a syntactically valid SQL identifier
                // and does not contain any SQL keywords, operators, or other malicious constructs.
                if (!VALID_SQL_IDENTIFIER_PATTERN.matcher(alias).matches()) {
                    throw new IllegalArgumentException("Invalid alias: Alias must start with a letter or underscore and contain only letters, numbers, or underscores.");
                }

                // Logic: Append alias to query
                // The 'alias' is now guaranteed to be a safe SQL identifier.
                this.query += " AS " + alias;
            }
            return this.query;
        }
    }

    /**
     * Annotiert Daten mit einem vom Benutzer bereitgestellten Alias.
     * 
     * Die Funktion validiert den Alias streng, um SQL-Injection zu verhindern.
     * Anstatt nur Semikolons zu blockieren, wird nun ein regulärer Ausdruck verwendet,
     * um sicherzustellen, dass der Alias nur gültige SQL-Identifikatorzeichen enthält
     * (beginnend mit einem Buchstaben oder Unterstrich, gefolgt von Buchstaben, Zahlen oder Unterstrichen).
     * Dies verhindert die Einschleusung von SQL-Keywords, Operatoren oder anderen bösartigen Konstrukten.
     */
}
