import java.io.File;

public class ClassX {
    /**
     * Trích xuất một thành viên cụ thể từ một kho lưu trữ (mô phỏng).
     * 
     * Hàm kiểm tra xem tên thành viên có bắt đầu bằng dấu gạch chéo hay không để ngăn chặn các đường dẫn tuyệt đối.
     *
     * @param memberName Tên của thành viên cần trích xuất.
     * @return Chuỗi đại diện cho đường dẫn an toàn của thành viên đã trích xuất (mô phỏng).
     * @throws IllegalArgumentException nếu tên thành viên bắt đầu bằng dấu gạch chéo (hoặc dấu gạch ngược),
     *                                  cho thấy một đường dẫn tuyệt đối không an toàn.
     */
    public String extractMember(String memberName) {
        if (memberName == null || memberName.trim().isEmpty()) {
            throw new IllegalArgumentException("Member name cannot be null or empty.");
        }

        // Prevent absolute paths by checking for leading slashes or backslashes.
        // This helps mitigate path traversal vulnerabilities.
        if (memberName.startsWith("/") || memberName.startsWith("\\")) {
            throw new IllegalArgumentException("Member name cannot start with a slash or backslash. Absolute paths are not allowed.");
        }

        // In a real scenario, this would involve logic to read the member
        // from an archive and write it to a safe location on the file system.
        // For this simulation, we simply return the validated member name.
        System.out.println("Simulating extraction of member: " + memberName);
        return memberName;
    }
}

