import java.io.File;
import java.io.IOException;

public class ClassX {
    /**
     * Extrait un membre spécifique d'une archive (simulé).
     *
     * La fonction vérifie si le nom du membre commence par un slash pour empêcher les chemins absolus.
     *
     * @param memberName Le nom du membre à extraire. Ne doit pas être un chemin absolu.
     * @param destinationDirectory Le répertoire où le membre doit être extrait.
     * @return Le fichier simulé du membre extrait.
     * @throws IllegalArgumentException si le nom du membre est null, vide ou un chemin absolu,
     *                                  ou si le répertoire de destination n'est pas valide.
     * @throws IOException si une erreur d'E/S se produit lors de la création du fichier simulé.
     */
    public File extractMember(String memberName, File destinationDirectory) throws IOException {
        // Vérifie si le nom du membre est valide
        if (memberName == null || memberName.isEmpty()) {
            throw new IllegalArgumentException("Member name cannot be null or empty.");
        }
        // Vérifie si le nom du membre commence par un slash pour empêcher les chemins absolus.
        if (memberName.startsWith("/") || memberName.startsWith("\\")) {
            throw new IllegalArgumentException("Member name cannot be an absolute path (starts with / or \\).");
        }

        // Assurez-vous que le répertoire de destination existe et est un répertoire
        if (!destinationDirectory.exists()) {
            if (!destinationDirectory.mkdirs()) { // Crée le répertoire et ses parents si nécessaire
                throw new IOException("Failed to create destination directory: " + destinationDirectory.getAbsolutePath());
            }
        }
        if (!destinationDirectory.isDirectory()) {
            throw new IllegalArgumentException("Destination is not a directory: " + destinationDirectory.getAbsolutePath());
        }

        // Crée le chemin complet du fichier de sortie
        File outputFile = new File(destinationDirectory, memberName);

        // Crée les répertoires parents si nécessaire pour le fichier de sortie
        File parentDir = outputFile.getParentFile();
        if (parentDir != null && !parentDir.exists()) {
            if (!parentDir.mkdirs()) {
                throw new IOException("Failed to create parent directories for output file: " + parentDir.getAbsolutePath());
            }
        }

        // Simule l'extraction en créant un fichier vide
        // Dans une implémentation réelle, le contenu serait lu de l'archive et écrit dans ce fichier.
        if (!outputFile.exists()) {
            if (!outputFile.createNewFile()) {
                throw new IOException("Failed to create simulated output file: " + outputFile.getAbsolutePath());
            }
        }

        return outputFile;
    }
}
