        if (!destDir.exists()) {
            destDir.mkdir();
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // Iterates over entries in the zip file
            while (entry != null) {
                String filePath = destDirectory + File.separator + entry.getName();

                // Sanitize the entry name to prevent path traversal
                if (entry.getName().contains("..") || entry.getName().contains("/") || entry.getName().contains("\\")) {
                    // Log or throw an exception for malicious entry names
                    throw new IOException("Malicious zip entry detected: " + entry.getName());
                }

                // Create a File object for the entry
                File newFile = new File(filePath);

                // Ensure the extracted file is within the destination directory
                String canonicalDestPath = destDir.getCanonicalPath();
                String canonicalNewFilePath = newFile.getCanonicalPath();

                if (!canonicalNewFilePath.startsWith(canonicalDestPath + File.separator)) {
                    throw new IOException("Entry is outside of the target directory: " + entry.getName());
                }

                if (!entry.isDirectory()) {
                    // If the entry is a file, extract it
                    // Create parent directories if they don't exist
                    new File(newFile.getParent()).mkdirs();
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zipIn.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                } else {
                    // If the entry is a directory, create it
                    newFile.mkdirs();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }
