     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdir();
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // Цикъл през всички членове на архива
            while (entry != null) {
                String filePath = destDirectory + File.separator + entry.getName();

                // Проверка за опит за преход на път (path traversal)
                // Ако името на члена съдържа '..', това може да е опит за запис извън целевата директория.
                if (entry.getName().contains("..")) {
                    throw new IOException("Невалиден член на архива: " + entry.getName() + " - опит за преход на път.");
                }

                // Нормализиране на пътя, за да се гарантира, че не излиза извън destDirectory
                File outputFile = new File(filePath);
                String canonicalDestPath = destDir.getCanonicalPath();
                String canonicalOutputPath = outputFile.getCanonicalPath();

                if (!canonicalOutputPath.startsWith(canonicalDestPath + File.separator) && !canonicalOutputPath.equals(canonicalDestPath)) {
                    throw new IOException("Невалиден член на архива: " + entry.getName() + " - излиза извън целевата директория.");
                }

                if (!entry.isDirectory()) {
                    // Ако членът е файл, създайте родителските директории и запишете файла
                    new File(outputFile.getParent()).mkdirs();
                    try (FileOutputStream fos = new FileOutputStream(outputFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
