                            fos.write(buffer, 0, len);
                        }
                    }
                } else {
                    // Ако членът е директория, просто я създайте
                    outputFile.mkdir();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }
