import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Belirtilen hedefe, üye yollarını kontrol ettikten sonra bir zip arşivini çıkarır.
     *
     * Fonksiyon, arşiv üyeleri arasında döngü yapar ve üye adının '..' içerip içermediğini kontrol ederek yol geçişini önlemeye çalışır.
     * Ayrıca, çıkarılan dosyanın hedef dizin içinde kalmasını sağlamak için kanonik yol kontrolü yapar.
     *
     * @param zipFilePath Zip arşiv dosyasının yolu.
     * @param destDirectory Çıkarılan dosyaların yerleştirileceği hedef dizin.
     * @throws IOException Çıkarma işlemi sırasında bir I/O hatası oluşursa.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        byte[] buffer = new byte[1024];
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();
            String destDirCanonicalPath = destDir.getCanonicalPath();

            while (zipEntry != null) {
                String fileName = zipEntry.getName();

                // Yol geçişi saldırılarını önlemek için güvenlik kontrolü
                // 1. '..' içeren yolları engelle
                if (fileName.contains("..")) {
                    throw new IOException("Zip entry contains '..' (path traversal attempt): " + fileName);
                }

                File newFile = new File(destDir, fileName);

                // 2. Çıkarılan dosyanın hedef dizin içinde kalmasını sağlamak için kanonik yol kontrolü
                String newFileCanonicalPath = newFile.getCanonicalPath();
                if (!newFileCanonicalPath.startsWith(destDirCanonicalPath + File.separator) && !newFileCanonicalPath.equals(destDirCanonicalPath)) {
                    throw new IOException("Zip entry attempts to write outside of destination directory: " + fileName);
                }

                if (zipEntry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Failed to create directory " + newFile);
                    }
                } else {
                    // Üst dizinlerin var olduğundan emin olun
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Failed to create directory " + parent);
                    }

                    // Dosyayı yaz
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipEntry = zis.getNextEntry();
            }
            zis.closeEntry();
        }
    }
}
