import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Extrae un archivo zip en la ubicación especificada después de verificar las rutas de los miembros.
     * 
     * La función itera a través de los miembros del archivo y intenta prevenir
     * la exploración de rutas verificando si el nombre del miembro contiene '..'.
     * 
     * @param zipFilePath La ruta completa del archivo zip a extraer.
     * @param destDirectory El directorio de destino donde se extraerán los archivos.
     * @throws IOException Si ocurre un error de E/S durante la extracción.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdir();
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // Itera sobre las entradas del archivo zip hasta que no haya más
            while (entry != null) {
                String entryName = entry.getName();

                // Prevención de Path Traversal:
                // Asegura que el nombre de la entrada no intente salir del directorio de destino.
                // También normaliza la ruta para evitar trucos con barras.
                File outputFile = new File(destDir, entryName);
                String canonicalDestinationPath = destDir.getCanonicalPath();
                String canonicalOutputPath = outputFile.getCanonicalPath();

                if (!canonicalOutputPath.startsWith(canonicalDestinationPath + File.separator)) {
                    // Si la ruta canónica del archivo de salida no comienza con la ruta canónica
                    // del directorio de destino (más un separador), entonces es un intento de
                    // path traversal.
                    throw new IOException("Entry is outside of the target directory: " + entryName);
                }

                // Otra forma más simple pero menos robusta para ciertos casos sería:
                // if (entryName.contains("..") || entryName.contains("/") || entryName.contains("\\")) {
                //     // Aquí se podría añadir una lógica más sofisticada si se desea permitir subdirectorios
                //     // pero prevenir ".." explícitamente.
                //     // La verificación canonicalPath es más robusta.
                // }


                if (entry.isDirectory()) {
                    // Si la entrada es un directorio, créalo
                    outputFile.mkdirs();
                } else {
                    // Asegura que los directorios padre existan para el archivo
                    outputFile.getParentFile().mkdirs();
                    // Si la entrada es un archivo, extrae su contenido
                    try (FileOutputStream fos = new FileOutputStream(outputFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zipIn.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }
}
