import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Extraheert een zip-archief naar de opgegeven bestemming na het controleren van de ledenpaden.
     * 
     * De functie doorloopt de leden van het archief en probeert paddoorsteek te voorkomen door te controleren of de ledennaam '..' bevat.
     *
     * @param zipFilePath Het pad naar het te extraheren zip-archief.
     * @param destDirectory Het pad naar de doelmap waar het archief moet worden uitgepakt.
     * @throws IOException Als er een I/O-fout optreedt tijdens het lezen of schrijven van bestanden,
     *                     of als een paddoorsteekpoging wordt gedetecteerd.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        byte[] buffer = new byte[1024]; // Buffer voor bestandslezen
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();
            while (zipEntry != null) {
                String fileName = zipEntry.getName();
                File newFile = new File(destDir, fileName);

                // Beveiliging tegen paddoorsteek (path traversal)
                // 1. Controleer op ".." in de bestandsnaam
                if (fileName.contains("..")) {
                    throw new IOException("Onveilige zip-entry: " + fileName + ". Bevat '..'");
                }

                // 2. Controleer of het canonieke pad binnen de doelmap blijft
                Path destDirPath = Paths.get(destDirectory).toRealPath();
                Path newFilePath = newFile.toPath().toRealPath();

                if (!newFilePath.startsWith(destDirPath)) {
                    throw new IOException("Onveilige zip-entry: " + fileName + ". Probeert buiten de doelmap te schrijven.");
                }

                if (zipEntry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Mislukt om map aan te maken: " + newFile);
                    }
                } else {
                    // Zorg ervoor dat de bovenliggende mappen bestaan voor het bestand
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Mislukt om bovenliggende mappen aan te maken voor: " + newFile);
                    }

                    // Schrijf het bestand weg
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipEntry = zis.getNextEntry();
            }
            zis.closeEntry();
        }
    }
}
