import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Extrait une archive zip vers la destination spécifiée après avoir vérifié les chemins des membres.
     *
     * La fonction parcourt les membres de l'archive et tente d'empêcher la traversée de chemin en vérifiant si le nom du membre contient '..'.
     *
     * @param zipFilePath Le chemin complet du fichier zip à extraire.
     * @param destDirectory Le chemin du répertoire de destination où les fichiers seront extraits.
     * @throws IOException Si une erreur d'entrée/sortie se produit pendant l'extraction.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        byte[] buffer = new byte[1024];
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();
            while (zipEntry != null) {
                String fileName = zipEntry.getName();

                // Vérification de la traversée de chemin
                // Empêche les chemins qui tentent de sortir du répertoire cible
                if (fileName.contains("..") || fileName.startsWith("/") || fileName.startsWith("\\")) {
                    System.err.println("Skipping potentially malicious zip entry: " + fileName);
                    zipEntry = zis.getNextEntry();
                    continue;
                }

                File newFile = new File(destDir, fileName);

                // Vérification supplémentaire pour s'assurer que le chemin résolu reste dans le répertoire de destination.
                // Cela est plus robuste que la simple vérification de `..` mais nécessite un chemin canonique.
                String destDirPath = destDir.getCanonicalPath();
                String newFilePath = newFile.getCanonicalPath();

                if (!newFilePath.startsWith(destDirPath + File.separator)) {
                    // Si le chemin résolu n'est pas un sous-chemin du répertoire de destination, il est malveillant.
                    System.err.println("Skipping potentially malicious zip entry (canonical path check): " + fileName);
                    zipEntry = zis.getNextEntry();
                    continue;
                }


                if (zipEntry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Failed to create directory " + newFile);
                    }
                } else {
                    // Créer tous les répertoires parents non existants
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Failed to create directory " + parent);
                    }

                    // Écrire le contenu du fichier
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipEntry = zis.getNextEntry();
            }
            zis.closeEntry();
        }
    }
}
