    /**
     * Onttrek 'n zip-argief na die gespesifiseerde bestemming nadat dit lidpade nagegaan is.
     * 
     * Die funksie herhaal deur die argieflede en probeer om padtravelling te voorkom deur te kyk of die lidnaam '..' bevat.
     *
     * @param zipFilePath Die pad na die zip-argief.
     * @param destDirectory Die gids waarheen die lêers onttrek moet word.
     * @throws IOException As 'n I/O-fout voorkom tydens onttrekking.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdir();
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // lus deur al die lêers in die zip-lêer
            while (entry != null) {
                String filePath = destDirectory + File.separator + entry.getName();

                // Voorkom padtravelling
                if (entry.getName().contains("..")) {
                    // Opsioneel: gooi 'n uitsondering of log 'n waarskuwing
                    System.err.println("Waarskuwing: Padtravelling poging in zip-inskrywing: " + entry.getName());
                    entry = zipIn.getNextEntry();
                    continue;
                }

                File newFile = new File(filePath);

                // Kontroleer of die onttrekte lêer binne die bestemmingsgids is
                String canonicalDestPath = destDir.getCanonicalPath();
                String canonicalNewFilePath = newFile.getCanonicalPath();

                if (!canonicalNewFilePath.startsWith(canonicalDestPath + File.separator)) {
                    // Hierdie kontrole is meer robuust as net 'contains("..")'
                    // Dit voorkom gevalle waar '..' op 'n meer gesofistikeerde manier gebruik word
                    throw new IOException("Poging tot padtravelling ontdek vir lêer: " + entry.getName());
