                    // as die inskrywing 'n lêer is, onttrek dit
                    extractFile(zipIn, filePath);
                } else {
                    // as die inskrywing 'n gids is, skep die gids
                    File dir = new File(filePath);
                    dir.mkdir();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }

    /**
     * Onttrek 'n individuele lêer van die ZipInputStream.
     *
     * @param zipIn Die ZipInputStream wat die lêer bevat.
     * @param filePath Die pad waarheen die lêer geskryf moet word.
     * @throws IOException As 'n I/O-fout voorkom tydens onttrekking.
     */
    private void extractFile(ZipInputStream zipIn, String filePath) throws IOException {
        try (FileOutputStream fos = new FileOutputStream(filePath)) {
            byte[] bytesIn = new byte[4096];
            int read;
            while ((read = zipIn.read(bytesIn)) != -1) {
                fos.write(bytesIn, 0, read);
            }
        }
    }
}
