        // Block semicolons, ampersands, pipes, backticks, and newlines
        String sanitizedHost = host.replaceAll("[;&|`\n\r]", "");

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;

        try {
            // Construct the ping command.
            // On Windows: "ping -n 1 " + sanitizedHost
            // On Linux/macOS: "ping -c 1 " + sanitizedHost
            String osName = System.getProperty("os.name").toLowerCase();
            String command;
            if (osName.contains("win")) {
                command = "ping -n 1 " + sanitizedHost;
            } else {
                command = "ping -c 1 " + sanitizedHost;
            }

            process = Runtime.getRuntime().exec(command);

            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Also read error stream in case of command failure
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }
            errorReader.close();

            int exitCode = process.waitFor();
            output.append("Exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("IOException during ping: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
