        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Log or handle closing error
                    output.append("Error closing reader: ").append(e.getMessage()).append("\n");
                }
            }
            if (process != null) {
                process.destroy(); // Ensure the process is terminated
            }
        }
        return output.toString();
    }

