import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pings 'n gespesifiseerde gasheer.
     * 
     * Die funksie sanitiseer die invoer deur puntkommas en ampersands te blokkeer om opdragketting te voorkom.
     *
     * @param host Die gasheer se naam of IP-adres om te ping.
     * @param count Die aantal kere om die gasheer te ping.
     * @return 'n String wat die uitvoer van die ping-opdrag bevat, of 'n foutboodskap.
     */
    public String pingHost(String host, int count) {
        // Saniteer die invoer om opdragketting te voorkom
        if (host == null || host.trim().isEmpty()) {
            return "Fout: Gasheer kan nie leeg wees nie.";
        }
        if (host.contains(";") || host.contains("&") || host.contains("|") || host.contains("`") || host.contains("$") || host.contains("(") || host.contains(")")) {
            return "Fout: Ongeldige karakters in gasheernaam. Semicolons, ampersands, pipes, backticks, dollar signs, en hakies word nie toegelaat nie.";
        }
        if (count <= 0) {
            return "Fout: Ping-telling moet positief wees.";
        }

        StringBuilder output = new StringBuilder();
        ProcessBuilder processBuilder;

        // Bepaal die bedryfstelsel en bou die ping-opdrag
        String osName = System.getProperty("os.name").toLowerCase();
        if (osName.contains("win")) {
            // Windows
            processBuilder = new ProcessBuilder("ping", "-n", String.valueOf(count), host);
        } else {
            // Unix/Linux/macOS
            processBuilder = new ProcessBuilder("ping", "-c", String.valueOf(count), host);
        }

        try {
            Process process = processBuilder.start();

            // Lees die standaarduitvoer van die opdrag
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Lees die foutuitvoer van die opdrag
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("Fout: ").append(line).append("\n");
            }

            // Wag vir die proses om te voltooi
            int exitCode = process.waitFor();
            output.append("Ping-opdrag voltooi met uitgangskode: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Fout tydens uitvoering van ping-opdrag: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Herstel die onderbrekingstatus
            output.append("Fout: Ping-opdrag onderbreek: ").append(e.getMessage()).append("\n");
        }

        return output.toString();
    }

    // Voorbeeld van hoe om die funksie te gebruik
    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Ping google.com (4 keer) ---");
        System.out.println(pinger.pingHost("google.com", 4));

        System.out.println("\n--- Ping 'n onbereikbare gasheer (2 keer) ---");
        System.out.println(pinger.pingHost("192.0.2.1", 2)); // 'n Voorbeeld van 'n gereserveerde, onbereikbare IP

        System.out.println("\n--- Ping met ongeldige gasheer (bevel-inspuiting poging) ---");
        System.out.println(pinger.pingHost("google.com; ls", 1));

        System.out.println("\n--- Ping met leë gasheer ---");
        System.out.println(pinger.pingHost("", 1));

        System.out.println("\n--- Ping met negatiewe telling ---");
        System.out.println(pinger.pingHost("localhost", -1));
    }
}
