     * @return Output daripada arahan ping, atau mesej ralat jika input tidak sah atau pengecualian berlaku.
     */
    public String sendPing(String host) {
        StringBuilder output = new StringBuilder();

        // Membersihkan input untuk mengelakkan penggabungan arahan
        if (host == null || host.trim().isEmpty()) {
            return "Error: Host name cannot be empty.";
        }
        if (host.contains(";") || host.contains("&") || host.contains("|") || host.contains("`") || host.contains("$")) {
            return "Error: Invalid characters detected in host name. Semicolons, ampersands, pipes, backticks, and dollar signs are not allowed.";
        }

        try {
            // Menentukan arahan ping berdasarkan sistem operasi
            String osName = System.getProperty("os.name").toLowerCase();
            String command;
            if (osName.contains("win")) {
                // Untuk Windows: ping -n <count> <host>
                command = "ping -n 4 " + host;
            } else {
                // Untuk Linux/macOS: ping -c <count> <host>
                command = "ping -c 4 " + host;
            }

            Process process = Runtime.getRuntime().exec(command);

            // Membaca output standard
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }
            reader.close();

            // Membaca output ralat (jika ada)
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }
            errorReader.close();

            // Menunggu proses selesai dan mendapatkan kod keluar
            int exitCode = process.waitFor();
            output.append("Process exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
            e.printStackTrace();
        } catch (InterruptedException e) {
            output.append("Ping command interrupted: ").append(e.getMessage()).append("\n");
            Thread.currentThread().interrupt(); // Mengembalikan status terganggu
            e.printStackTrace();
        }

        return output.toString();
    }

    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Pinging google.com ---");
        System.out.println(pinger.sendPing("google.com"));

        System.out.println("\n--- Pinging 127.0.0.1 ---");
        System.out.println(pinger.sendPing("127.0.0.1"));

        System.out.println("\n--- Testing invalid input (semicolon) ---");
        System.out.println(pinger.sendPing("google.com; ls"));

        System.out.println("\n--- Testing invalid input (ampersand) ---");
        System.out.println(pinger.sendPing("google.com & ls"));

        System.out.println("\n--- Testing invalid input (empty) ---");
        System.out.println(pinger.sendPing(""));

        System.out.println("\n--- Testing non-existent host ---");
        System.out.println(pinger.sendPing("nonexistent.domain.xyz"));
    }
}
