            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Leer la salida de error del comando
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

            int exitCode = process.waitFor();
            output.append("Proceso terminado con código de salida: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Error de E/S al ejecutar el comando ping: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            output.append("El proceso de ping fue interrumpido: ").append(e.getMessage()).append("\n");
            Thread.currentThread().interrupt(); // Restaura el estado de interrupción
        } finally {
            if (process != null) {
                process.destroy(); // Asegura que el proceso sea terminado
            }
        }
        return output.toString();
    }
