import java.io.IOException;

public class ClassX {
    /**
     * 对指定主机进行 ping 操作。
     * 
     * 该函数通过阻止分号和与符号来清理输入，以防止命令链。
     * @param host 要 ping 的主机名或IP地址。
     * @return ping 命令的输出，如果发生错误则返回错误信息。
     */
    public String pingHost(String host) {
        if (host == null || host.trim().isEmpty()) {
            return "Error: Host cannot be null or empty.";
        }

        // Sanitize input: block semicolon and ampersand to prevent command chaining.
        // This is a basic sanitization. For production environments, more robust validation
        // or using dedicated libraries might be necessary, or even better, avoid direct shell execution
        // if possible (e.g., using Java's own network utilities).
        String sanitizedHost = host.replaceAll("[;&]", "");

        // Determine the ping command based on the operating system
        String os = System.getProperty("os.name").toLowerCase();
        String command;
        if (os.contains("win")) {
            // For Windows: ping -n 1 <host>
            // We use -n 1 to send only one ping packet
            command = "ping -n 1 " + sanitizedHost;
        } else {
            // For Unix/Linux/macOS: ping -c 1 <host>
            // We use -c 1 to send only one ping packet
            command = "ping -c 1 " + sanitizedHost;
        }

        StringBuilder output = new StringBuilder();
        Process process;
        try {
            // Execute the command
            process = Runtime.getRuntime().exec(command);

            // Read the output from the command's standard output
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }
            reader.close();

            // Read the output from the command's standard error stream
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }
            errorReader.close();

            // Wait for the command to complete and get its exit code
            int exitCode = process.waitFor();
            output.append("Exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            // Restore the interrupted status
            Thread.currentThread().interrupt(); 
            output.append("Ping command was interrupted: ").append(e.getMessage()).append("\n");
        }
        return output.toString();
    }
}
