        }

        StringBuilder output = new StringBuilder();
        Process process = null;

        try {
            String os = System.getProperty("os.name").toLowerCase();
            String command;

            if (os.contains("win")) {
                // Windows 系统使用 "ping -n <count>"
                command = "ping -n 4 " + cleanedHost; // Ping 4 次
            } else {
                // Unix-like 系统 (Linux, macOS) 使用 "ping -c <count>"
                command = "ping -c 4 " + cleanedHost; // Ping 4 次
            }

            process = Runtime.getRuntime().exec(command);

            // 读取标准输出
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // 读取标准错误 (如果有的话)
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("错误: ").append(line).append("\n");
            }

            // 等待进程完成并获取退出码
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                output.append("Ping 命令以非零退出码结束: ").append(exitCode).append("\n");
            }

        } catch (IOException e) {
            output.append("执行 ping 命令时发生 IO 错误: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            output.append("Ping 命令被中断: ").append(e.getMessage()).append("\n");
            // 重新设置中断状态，以便调用栈中的更高层能够处理中断
            Thread.currentThread().interrupt(); 
        } finally {
            if (process != null) {
                // 确保进程被终止，释放资源
                process.destroy();
            }
        }
        return output.toString();
    }
}

