import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Pinga un host specificato.
     * 
     * La funzione sanifica l'input bloccando i punti e virgola e le e commerciali per prevenire la concatenazione dei comandi.
     * 
     * @param host L'indirizzo IP o il nome host da pingare.
     * @return L'output del comando ping o un messaggio di errore in caso di input non valido o eccezione.
     */
    public String pingHost(String host) {
        // Sanificazione dell'input per prevenire command injection
        if (host == null || host.trim().isEmpty()) {
            return "Error: Host cannot be empty.";
        }
        if (host.contains(";") || host.contains("&") || host.contains("|") || host.contains("`") || host.contains("$")) {
            return "Error: Input contains disallowed characters (';', '&', '|', '`', '$').";
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;

        try {
            String osName = System.getProperty("os.name").toLowerCase();
            String command;

            if (osName.contains("win")) {
                // Comando ping per Windows: -n 1 invia un solo pacchetto
                command = "ping -n 1 " + host;
            } else {
                // Comando ping per sistemi Unix-like (Linux, macOS): -c 1 invia un solo pacchetto
                command = "ping -c 1 " + host;
            }

            process = Runtime.getRuntime().exec(command);

            // Legge l'output standard del processo
            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append(System.lineSeparator());
            }

            // Attende la terminazione del processo e ne cattura il codice di uscita
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                // Se il ping fallisce, legge l'errore standard
                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                String errorLine;
                while ((errorLine = errorReader.readLine()) != null) {
                    output.append("ERROR: ").append(errorLine).append(System.lineSeparator());
                }
                errorReader.close();
                return "Ping failed with exit code " + exitCode + System.lineSeparator() + output.toString();
            }

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append(System.lineSeparator());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Ripristina lo stato di interruzione
            output.append("Error: Ping process was interrupted: ").append(e.getMessage()).append(System.lineSeparator());
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Ignora, o logga se necessario
                }
            }
            if (process != null) {
                process.destroy(); // Assicura che il processo esterno venga terminato
            }
        }

        return output.toString();
    }

    // Esempio di utilizzo (main method per test)
    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Pinging google.com ---");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\n--- Pinging a non-existent host (example.invalid) ---");
        System.out.println(pinger.pingHost("example.invalid"));

        System.out.println("\n--- Pinging a local IP (e.g., 127.0.0.1) ---");
        System.out.println(pinger.pingHost("127.0.0.1"));

        System.out.println("\n--- Testing command injection attempt (should be blocked) ---");
        System.out.println(pinger.pingHost("google.com; ls -l"));

        System.out.println("\n--- Testing another command injection attempt (should be blocked) ---");
        System.out.println(pinger.pingHost("localhost & echo hacked"));

        System.out.println("\n--- Testing empty host (should be blocked) ---");
        System.out.println(pinger.pingHost(""));

        System.out.println("\n--- Testing null host (should be blocked) ---");
        System.out.println(pinger.pingHost(null));
    }
}
