        // per prevenire la concatenazione di comandi (command injection).
        String sanitizedHost = host.replaceAll("[;&]", "");

        // Costruisci il comando di ping.
        // Su sistemi operativi diversi (es. Windows vs Linux/macOS), il comando
        // di ping potrebbe avere opzioni leggermente diverse,
        // ma "ping <host>" è generalmente universale per un ping di base.
        // Per maggiore robustezza, si potrebbe voler specificare un numero di pacchetti (es. -n 1 su Windows, -c 1 su Linux).
        // Per semplicità, usiamo la forma base.
        String command = "ping " + sanitizedHost;

        System.out.println("Esecuzione del comando: " + command);
        System.out.println("Host sanificato: " + sanitizedHost);

        try {
            // Esegui il comando di ping.
            Process process = Runtime.getRuntime().exec(command);

            // Leggi l'output standard del comando.
            BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String s;
            System.out.println("Output del ping:");
            while ((s = stdInput.readLine()) != null) {
                System.out.println(s);
            }

            // Leggi l'output di errore del comando (se presente).
            BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            String err;
            boolean hasError = false;
            while ((err = stdError.readLine()) != null) {
                if (!hasError) {
                    System.err.println("Errore durante l'esecuzione del ping:");
                    hasError = true;
                }
                System.err.println(err);
            }

            // Attendi che il processo termini e ottieni il codice di uscita.
            int exitCode = process.waitFor();
            System.out.println("Il comando di ping è terminato con codice di uscita: " + exitCode);

        } catch (IOException e) {
            System.err.println("Si è verificato un errore I/O durante l'esecuzione del comando di ping: " + e.getMessage());
            e.printStackTrace();
        } catch (InterruptedException e) {
            System.err.println("Il thread corrente è stato interrotto mentre attendeva la terminazione del processo di ping: " + e.getMessage());
            Thread.currentThread().interrupt(); // Ripristina lo stato di interruzione
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Test 1: Host valido ---");
        pinger.pingHost("localhost");
        System.out.println("\n");

        System.out.println("--- Test 2: Host valido (IP) ---");
        pinger.pingHost("127.0.0.1");
