import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Belirtilen bir ana bilgisayara ping atar.
     * 
     * Fonksiyon, komut zincirlemesini önlemek için girişte noktalı virgülleri ve ampersandları engelleyerek veriyi temizler.
     *
     * @param host Ping atılacak ana bilgisayar adı veya IP adresi.
     * @return Ping komutunun çıktısı. Hata durumunda hata mesajını içerir.
     */
    public String pingHost(String host) {
        StringBuilder output = new StringBuilder();
        // Komut zincirlemesini önlemek için noktalı virgülleri ve ampersandları kaldır.
        // Daha güvenli bir yaklaşım için ProcessBuilder kullanmak veya daha kapsamlı sanitizasyon yapmak gerekebilir.
        String sanitizedHost = host.replaceAll("[;&]", "");

        try {
            String os = System.getProperty("os.name").toLowerCase();
            String command;

            if (os.contains("win")) {
                // Windows sistemleri için ping komutu
                command = "ping -n 4 " + sanitizedHost;
            } else {
                // Linux/macOS vb. sistemler için ping komutu
                command = "ping -c 4 " + sanitizedHost;
            }

            Process process = Runtime.getRuntime().exec(command);

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }
            reader.close();

            // Hata akışını da oku
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }
            errorReader.close();

            int exitVal = process.waitFor();
            output.append("Exited with error code: ").append(exitVal).append("\n");

        } catch (IOException e) {
            output.append("An I/O error occurred: ").append(e.getMessage()).append("\n");
            // e.printStackTrace(); // Hata ayıklama için kullanılabilir
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Kesintiye uğramış durumu geri yükle
            output.append("The ping process was interrupted: ").append(e.getMessage()).append("\n");
            // e.printStackTrace(); // Hata ayıklama için kullanılabilir
        } catch (Exception e) {
            output.append("An unexpected error occurred: ").append(e.getMessage()).append("\n");
            // e.printStackTrace(); // Hata ayıklama için kullanılabilir
        }
        return output.toString();
    }
}
