import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Пингва определен хост.
     *
     * Функцията почиства входа, като блокира точките и амперсандите, за да предотврати свързването на команди.
     *
     * @param host Адресът на хоста за пингване.
     * @return Резултатът от пинг командата като низ, или съобщение за грешка.
     */
    public String pingHost(String host) {
        // Почистване на входа: блокиране на точки и амперсанди
        // Това е базова защита срещу инжектиране на команди.
        // За по-сериозни приложения трябва да се използва по-строга валидация или да се избягва директното изпълнение на шел команди.
        String sanitizedHost = host.replaceAll("[.&]", "");

        if (sanitizedHost.isEmpty()) {
            return "Грешка: Невалиден или почистен хост.";
        }

        StringBuilder output = new StringBuilder();
        Process p;
        try {
            // Определяне на командата за пинг в зависимост от операционната система
            String osName = System.getProperty("os.name").toLowerCase();
            String command;
            if (osName.contains("win")) {
                // Windows: ping -n 1 <host>
                command = "ping -n 1 " + sanitizedHost;
            } else {
                // Unix/Linux/macOS: ping -c 1 <host>
                command = "ping -c 1 " + sanitizedHost;
            }

            p = Runtime.getRuntime().exec(command);
            p.waitFor(); // Изчакваме изпълнението на командата

            BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Проверка за грешки от стандартния изход за грешки
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(p.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("Грешка: ").append(line).append("\n");
            }

        } catch (IOException e) {
            output.append("Грешка при изпълнение на команда: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Възстановяване на прекъснатия статус
            output.append("Грешка: Изпълнението на командата беше прекъснато.").append("\n");
        }

        return output.toString();
    }

    // Пример за използване
    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("Пингване на google.com:");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\nПингване на localhost:");
        System.out.println(pinger.pingHost("localhost"));

        System.out.println("\nПингване с опит за инжекция (google.com & ls -la):");
        System.out.println(pinger.pingHost("google.com & ls -la")); // Очаква се & да бъде премахнато

        System.out.println("\nПингване с опит за инжекция (127.0.0.1; rm -rf /):");
        System.out.println(pinger.pingHost("127.0.0.1; rm -rf /")); // Очаква се ; да не бъде премахнато от текущата логика, но . ще бъде

        System.out.println("\nПингване на несъществуващ хост (nonexistent.example.com):");
        System.out.println(pinger.pingHost("nonexistent.example.com"));
    }
}
