     */
    public String generateCleanedTemplate(String userInput) {
        if (userInput == null || userInput.isEmpty()) {
            return userInput;
        }

        String cleanedInput = userInput;

        // Block Jinja2 variable delimiters: {{ ... }}
        // By inserting a space, the sequence is broken and will not be parsed by Jinja2.
        cleanedInput = cleanedInput.replace("{{", "{ {");
        cleanedInput = cleanedInput.replace("}}", "} }");

        // Block Jinja2 statement delimiters: {% ... %}
        cleanedInput = cleanedInput.replace("{%", "{ %");
        cleanedInput = cleanedInput.replace("%}", "% }");

        // Block Jinja2 comment delimiters: {# ... #}
        cleanedInput = cleanedInput.replace("{#", "{ #");
        cleanedInput = cleanedInput.replace("#}", "# }");

        return cleanedInput;
    }
}
