    public String getContentFromValidatedUrl(URL url) throws IOException {
        if (url == null) {
            throw new IllegalArgumentException("URL tidak boleh null.");
        }

        String host = url.getHost();

        // Validasi host: Pastikan host tidak null atau kosong dan tidak mengandung spasi.
        // Host yang null atau kosong bisa terjadi pada URL tanpa otoritas (misalnya "file:///path/to/file").
        // Namun, untuk validasi host seperti yang diminta, kita asumsikan host harus ada.
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host URL tidak ditemukan atau kosong.");
        }

        // Memeriksa karakter tidak valid seperti spasi dalam host.
        // Validasi yang lebih komprehensif mungkin melibatkan regex untuk nama host yang valid (RFCs).
        if (host.contains(" ")) {
            throw new IllegalArgumentException("Host URL mengandung karakter spasi yang tidak valid: " + host);
        }

        StringBuilder content = new StringBuilder();
        URLConnection connection = url.openConnection();

        // Membaca konten dari URL menggunakan UTF-8 sebagai encoding standar
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
                content.append(System.lineSeparator()); // Mempertahankan pemisah baris
            }
        }

        // Menghapus pemisah baris terakhir jika ada, karena ditambahkan setelah baris terakhir
        if (content.length() > 0 && content.toString().endsWith(System.lineSeparator())) {
            content.setLength(content.length() - System.lineSeparator().length());
        }

        return content.toString();
    }
}
