     * @throws IllegalArgumentException Если хост содержит недопустимые символы (например, пробелы) или является пустым.
     */
    public String getContentFromUrl(String host, String path) throws IOException {
        // Проверка и очистка хоста
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Хост не может быть null или пустым.");
        }
        if (host.contains(" ")) {
            throw new IllegalArgumentException("Хост содержит недопустимые символы (пробелы).");
        }
        // Дополнительные проверки могут быть добавлены здесь для более строгой валидации хоста

        URL url;
        try {
            // Предполагаем использование HTTPS как стандартного безопасного протокола.
            // Если требуется HTTP, схему можно сделать параметром или использовать другую логику.
            url = new URL("https", host, path);
        } catch (MalformedURLException e) {
            throw new IOException("Не удалось создать URL: " + e.getMessage(), e);
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
                content.append(System.lineSeparator()); // Добавляем разделитель строк для сохранения формата
            }
        }

        // Удаляем последний разделитель строк, если он был добавлен и нет содержимого после него
        if (content.length() > 0 && content.toString().endsWith(System.lineSeparator())) {
            content.setLength(content.length() - System.lineSeparator().length());
        }

        return content.toString();
    }
