import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.MalformedURLException;
import java.net.URL;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Получает содержимое с сгенерированного URL после проверки хоста.
     *
     * Эта функция очищает хост, проверяя наличие недопустимых символов, таких как пробелы.
     *
     * @param host Неочищенный строковый хост (например, " example.com ").
     * @return Содержимое URL в виде строки.
     * @throws IOException Если произошла ошибка ввода-вывода при открытии или чтении URL.
     * @throws IllegalArgumentException Если предоставленный хост является null, пустым,
     *                                  или если после очистки он не является действительным хостом
     *                                  для формирования URL.
     */
    public String getContentFromValidatedHost(String host) throws IOException {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }

        // Очистка хоста: удаление начальных/конечных пробелов и любых пробелов внутри строки хоста.
        // Более строгая валидация может включать регулярные выражения для проверки формата имени хоста.
        // В этом примере мы сосредоточимся на требовании "таких как пробелы".
        String cleanedHost = host.trim().replace(" ", "");

        // Базовая валидация: если после очистки строка хоста пуста, это недопустимо.
        if (cleanedHost.isEmpty()) {
            throw new IllegalArgumentException("Host is invalid after cleaning (e.g., only contained spaces).");
        }

        // Формирование URL. Для простоты предполагается протокол HTTP и корневой путь.
        // В реальном приложении протокол и путь могут быть параметрами или конфигурироваться.
        URL url;
        try {
            // Попытка создать URL. Конструктор URL сам выполнит некоторую валидацию.
            // Используем протокол по умолчанию (http) и простой путь (корень).
            url = new URL("http://" + cleanedHost + "/");
        } catch (MalformedURLException e) {
            // Если очищенный хост все равно приводит к неверному URL, это недопустимый хост.
            throw new IllegalArgumentException("Invalid host provided: " + cleanedHost, e);
        }

        StringBuilder content = new StringBuilder();
        // Открытие потока и чтение содержимого URL
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(url.openStream(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append(System.lineSeparator());
            }
        }
        return content.toString();
    }
}
