     *
     * @param host Die gasheer om te gebruik in die URL.
     * @param path Die pad om te gebruik in die URL.
     * @return Die inhoud van die URL as 'n string, of null as 'n fout voorkom.
     */
    public String fetchContentFromVerifiedHost(String host, String path) {
        // 1. Saniteer die gasheer
        if (host == null || host.trim().isEmpty()) {
            System.err.println("Fout: Gasheer kan nie leeg wees nie.");
            return null;
        }

        // Verwyder witspasies en ander moontlik ongeldige karakters.
        // Vir 'n meer robuuste sanitering, kan 'n whitelist van karakters gebruik word
        // of 'n regex om te verseker dit is 'n geldige domeinnaam of IP-adres.
        String sanitizedHost = host.trim();
        if (sanitizedHost.contains(" ") || sanitizedHost.contains("\t") || sanitizedHost.contains("\n")) {
            System.err.println("Fout: Gasheer bevat ongeldige witspasie karakters.");
            return null;
        }
        // Verdere sanitering/validasie kan hier bygevoeg word, bv. regex vir geldige domeinnaam.
        // Voorbeeld: if (!sanitizedHost.matches("^[a-zA-Z0-9.-]+$")) { ... }

        // 2. Genereer die URL
        URL url = null;
        try {
            // Ons veronderstel 'n HTTP-protokol vir hierdie voorbeeld.
            // In 'n produksie-omgewing, oorweeg HTTPS.
            url = new URL("http", sanitizedHost, path);
        } catch (MalformedURLException e) {
            System.err.println("Fout by die skep van URL: " + e.getMessage());
            return null;
        }

        // 3. Haal inhoud af
        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            // Stel 'n tydsverloop in om te verhoed dat die toepassing vir ewig wag
            connection.setConnectTimeout(5000); // 5 sekondes vir konneksie
            connection.setReadTimeout(10000); // 10 sekondes vir lees

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append("\n");
                }
            }
        } catch (IOException e) {
            System.err.println("Fout by die aflaai van inhoud vanaf " + url.toString() + ": " + e.getMessage());
            return null;
        }

        return content.toString();
    }

    public static void main(String[] args) {
        ClassX instance = new ClassX();

        // Voorbeelde van gebruik:
        System.out.println("--- Geldige Gasheer ---");
        String validContent = instance.fetchContentFromVerifiedHost("example.com", "/");
        if (validContent != null) {
            System.out.println("Inhoud van example.com:\n" + validContent.substring(0, Math.min(validContent.length(), 200)) + "...");
        }

        System.out.println("\n--- Gasheer met ongeldige karakters ---");
        String invalidHostContent = instance.fetchContentFromVerifiedHost(" my bad host.com ", "/");
        if (invalidHostContent == null) {
            System.out.println("Korrek hanteer: Ongeldige gasheer is geblokkeer.");
        }

        System.out.println("\n--- Leë Gasheer ---");
        String emptyHostContent = instance.fetchContentFromVerifiedHost("", "/");
        if (emptyHostContent == null) {
            System.out.println("Korrek hanteer: Leë gasheer is geblokkeer.");
        }

        System.out.println("\n--- Nie-bestaande Gasheer (sal waarskynlik 'n fout gee) ---");
        String nonExistentHostContent = instance.fetchContentFromVerifiedHost("nonexistent.example.com", "/");
        if (nonExistentHostContent == null) {
            System.out.println("Korrek hanteer: Kon nie inhoud van nie-bestaande gasheer aflaai nie.");
        }
    }
}
