     * @throws IOException Se ocorrer um erro ao conectar ou ler da URL.
     */
    public String fetchContentFromValidatedUrl(String host, String path)
            throws IllegalArgumentException, MalformedURLException, IOException {

        // 1. Sanitize the host
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }
        String sanitizedHost = host.trim(); // Remove leading/trailing whitespace

        // Check for invalid characters, specifically spaces as mentioned in the description.
        // A more comprehensive validation might use a regular expression for valid hostname characters.
        if (sanitizedHost.contains(" ")) {
            throw new IllegalArgumentException("Host contains invalid characters (spaces).");
