        // 2. Construct the URL
        // Using "http" as the default protocol. This could be made configurable if needed.
        // The URL constructor handles proper encoding of path components.
        URL url = new URL("http", sanitizedHost, path);

        // 3. Fetch content from the URL
        URLConnection connection = url.openConnection();
        // Set timeouts to prevent indefinite waiting
        connection.setConnectTimeout(5000); // 5 seconds for connection establishment
        connection.setReadTimeout(10000);   // 10 seconds for reading data

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
