import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.URLConnection;

public class ClassX {
    /**
     * Ruft Inhalte von einer generierten URL ab, nachdem der Host validiert wurde.
     *
     * Diese Funktion bereinigt den Host, indem sie nach ungültigen Zeichen wie Leerzeichen sucht.
     *
     * @param rawHost Der unbereinigte Host-String, der validiert und bereinigt werden soll.
     * @return Der Inhalt der generierten URL als String.
     * @throws IllegalArgumentException Wenn der übergebene Host null, leer ist oder nach der Bereinigung ungültig wird.
     * @throws MalformedURLException Wenn die generierte URL syntaktisch fehlerhaft ist.
     * @throws IOException Wenn beim Herstellen der Verbindung oder beim Lesen der Inhalte ein Fehler auftritt.
     */
    public String retrieveContentFromValidatedHost(String rawHost) throws MalformedURLException, IOException {
        if (rawHost == null || rawHost.trim().isEmpty()) {
            throw new IllegalArgumentException("Der Host darf nicht null oder leer sein.");
        }

        // 1. Host bereinigen
        // Entfernt führende/nachfolgende Leerzeichen und alle inneren Leerzeichen.
        String cleanedHost = rawHost.trim().replaceAll("\\s+", "");

        if (cleanedHost.isEmpty()) {
            throw new IllegalArgumentException("Der Host ist nach der Bereinigung leer.");
        }

        // 2. URL generieren
        // Annahme: Wir generieren eine einfache HTTP-URL.
        // In einem realen Szenario könnte hier auch HTTPS verwendet werden oder ein spezifischer Pfad.
        String urlString = "http://" + cleanedHost + "/";
        URL url = new URL(urlString);

        // 3. Inhalte abrufen
        StringBuilder content = new StringBuilder();
        URLConnection connection = url.openConnection();

        // Optional: Setze einen Timeout für die Verbindung und das Lesen
        connection.setConnectTimeout(5000); // 5 Sekunden
        connection.setReadTimeout(10000);   // 10 Sekunden

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
                content.append(System.lineSeparator()); // Behält Zeilenumbrüche bei
            }
        } catch (IOException e) {
            throw new IOException("Fehler beim Abrufen der Inhalte von der URL: " + urlString, e);
        }

        return content.toString();
    }
}
