     * @return Το περιεχόμενο ως String.
     * @throws IllegalArgumentException Εάν ο κεντρικός υπολογιστής περιέχει μη έγκυρους χαρακτήρες (π.χ. κενά).
     * @throws MalformedURLException Εάν η κατασκευασμένη διεύθυνση URL είναι εσφαλμένη.
     * @throws IOException Εάν προκύψει σφάλμα κατά την ανάκτηση του περιεχομένου.
     */
    public String retrieveContentFromValidatedUrl(String host, String path) throws IllegalArgumentException, MalformedURLException, IOException {
        // Επικύρωση του κεντρικού υπολογιστή: έλεγχος για μη έγκυρους χαρακτήρες όπως κενά.
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Ο κεντρικός υπολογιστής δεν μπορεί να είναι κενός.");
        }
        if (host.contains(" ") || host.contains("\t") || host.contains("\n") || host.contains("\r")) {
            throw new IllegalArgumentException("Ο κεντρικός υπολογιστής περιέχει μη έγκυρους χαρακτήρες (π.χ. κενά).");
        }

        // Κατασκευή της διεύθυνσης URL. Υποθέτουμε HTTPS για ασφάλεια.
        // Βεβαιωθείτε ότι η διαδρομή ξεκινά με '/'
        String fullPath = path;
        if (path != null && !path.startsWith("/")) {
            fullPath = "/" + path;
        } else if (path == null) {
            fullPath = "";
        }

        URL url = new URL("https", host, fullPath);

        // Άνοιγμα σύνδεσης και ανάκτηση περιεχομένου
        URLConnection connection = url.openConnection();
        connection.setRequestProperty("User-Agent", "Mozilla/5.0"); // Ορισμός User-Agent για συμβατότητα

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }

        return content.toString();
    }
}
