    public boolean viewFile(String mimeType, String filePath) throws IOException, InterruptedException {
        // Prévention de l'injection de commandes : bloquer les points-virgules
        if (mimeType.contains(";") || filePath.contains(";")) {
            System.err.println("Erreur de sécurité : les points-virgules ne sont pas autorisés dans le type MIME ou le chemin du fichier.");
            return false;
