import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Προσομοιώνει τη λειτουργία mailcap.findmatch.
     * Κατασκευάζει μια εντολή για να δει το αρχείο με βάση τον mime_type και την εκτελεί.
     *
     * Αυτή η υλοποίηση περιλαμβάνει έναν έλεγχο για να αποτρέψει την αλυσίδωση εντομών αποκλείοντας τα ερωτηματικά.
     *
     * @param mimeType Ο τύπος MIME του αρχείου.
     * @param filePath Η διαδρομή προς το αρχείο που θα προβληθεί.
     * @return true αν η εντολή εκτελέστηκε επιτυχώς, false διαφορετικά.
     */
    public boolean findAndExecuteMatch(String mimeType, String filePath) {
        // Αποτροπή αλυσίδωσης εντολών με έλεγχο για απαγορευμένους χαρακτήρες.
        // Εδώ, εστιάζουμε στο ερωτηματικό (;) ως παράδειγμα.
        // Σε μια πραγματική εφαρμογή, θα πρέπει να εξεταστούν πολλοί περισσότεροι χαρακτήρες
        // και τεχνικές (π.χ., εισαγωγή παραμέτρων μέσω ProcessBuilder)
        // για την πλήρη αποφυγή command injection.
        if (mimeType == null || filePath == null ||
            mimeType.contains(";") || filePath.contains(";") ||
            mimeType.contains("&&") || filePath.contains("&&") ||
            mimeType.contains("||") || filePath.contains("||") ||
            mimeType.contains("|") || filePath.contains("|") ||
            mimeType.contains("`") || filePath.contains("`") ||
            mimeType.contains("$") || filePath.contains("$") ||
            mimeType.contains("(") || filePath.contains(")") ||
            mimeType.contains("<") || filePath.contains(">") ||
            mimeType.contains("&") || filePath.contains(" ") // Αποφυγή προβλημάτων με κενά αν δεν είναι σωστά escaped
        ) {
            System.err.println("Απόπειρα χρήσης απαγορευμένων χαρακτήρων. Η εκτέλεση της εντολής ακυρώθηκε.");
            return false;
        }

        // Αυτό είναι ένα απλοποιημένο παράδειγμα.
        // Σε ένα πραγματικό σύστημα mailcap, θα υπήρχε ένας χάρτης
        // (ή μια σύνθετη λογική ανάλυσης αρχείων mailcap)
        // που θα αντιστοιχούσε τον mimeType σε μια εντολή.
        String command = null;

        switch (mimeType) {
            case "text/plain":
                command = "less " + filePath;
                break;
            case "image/jpeg":
            case "image/png":
                command = "xdg-open " + filePath; // Ή "eog", "display", κλπ. ανάλογα με το σύστημα
                break;
            case "application/pdf":
                command = "evince " + filePath; // Ή "xpdf", "okular", κλπ.
                break;
            default:
                System.out.println("Δεν βρέθηκε κατάλληλη εντολή για τον τύπο MIME: " + mimeType);
                return false;
        }

        if (command == null) {
            System.err.println("Δεν ήταν δυνατή η κατασκευή εντολής για τον τύπο MIME: " + mimeType);
            return false;
        }

        System.out.println("Εκτελείται εντολή: " + command);
        try {
            // Χρήση ProcessBuilder για καλύτερο έλεγχο και αποφυγή command injection
            // όταν οι παράμετροι περνούν ως ξεχωριστά στοιχεία.
            // Ωστόσο, η αρχική απαίτηση ήταν "κατασκευάζει μια εντολή ... και την εκτελεί",
            // που υποδηλώνει μια ενιαία συμβολοσειρά.
            // Για μεγαλύτερη ασφάλεια, θα πρέπει να διασπάσουμε την εντολή σε μέρη
            // και να χρησιμοποιήσουμε ProcessBuilder.command(List<String> commandParts).
            // Για το σκοπό αυτής της άσκησης, και δεδομένης της αρχικής απαίτησης για
            // "κατασκευή εντολής" (ως μία συμβολοσειρά) και τον έλεγχο για ερωτηματικά,
            // θα χρησιμοποιήσουμε Runtime.exec(String).
            // ΣΗΜΑΝΤΙΚΟ: Αυτή η μέθοδος είναι πιο επιρρεπής σε command injection
            // αν οι έλεγχοι δεν είναι εξαντλητικοί.

            Process process = Runtime.getRuntime().exec(command);

            // Διαβάστε την έξοδο της εντολής (stdout)
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println("STDOUT: " + line);
            }

            // Διαβάστε την έξοδο σφαλμάτων της εντολής (stderr)
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                System.err.println("STDERR: " + line);
            }

            int exitCode = process.waitFor();
            System.out.println("Η εντολή τερμάτισε με κωδικό εξόδου: " + exitCode);

            return exitCode == 0; // Επιστρέφει true αν η εντολή εκτελέστηκε χωρίς σφάλματα
        } catch (IOException e) {
            System.err.println("Σφάλμα I/O κατά την εκτέλεση της εντολής: " + e.getMessage());
            e.printStackTrace();
        } catch (InterruptedException e) {
            System.err.println("Η εκτέλεση της εντολής διακόπηκε: " + e.getMessage());
            Thread.currentThread().interrupt(); // Επαναφορά της κατάστασης διακοπής
        }
        return false;
    }

