        ClassX mailcapSimulator = new ClassX();

        System.out.println("--- Δοκιμή 1: Έγκυρη εντολή (text/plain) ---");
        mailcapSimulator.findAndExecuteMatch("text/plain", "/tmp/testfile.txt");
        // Δημιουργήστε ένα αρχείο /tmp/testfile.txt για να λειτουργήσει αυτή η δοκιμή
        // echo "Hello, world!" > /tmp/testfile.txt

        System.out.println("\n--- Δοκιμή 2: Έγκυρη εντολή (image/jpeg) ---");
        mailcapSimulator.findAndExecuteMatch("image/jpeg", "/tmp/image.jpg");
        // Δημιουργήστε ένα αρχείο /tmp/image.jpg (π.χ., αντιγράψτε μια εικόνα)

        System.out.println("\n--- Δοκιμή 3: Απαγορευμένοι χαρακτήρες στο filePath (;) ---");
        mailcapSimulator.findAndExecuteMatch("text/plain", "/tmp/file.txt; rm -rf /");

        System.out.println("\n--- Δοκιμή 4: Απαγορευμένοι χαρακτήρες στο mimeType (&&) ---");
        mailcapSimulator.findAndExecuteMatch("text/plain && ls", "/tmp/another.txt");

        System.out.println("\n--- Δοκιμή 5: Μη υποστηριζόμενος MIME τύπος ---");
        mailcapSimulator.findAndExecuteMatch("application/zip", "/tmp/archive.zip");

        System.out.println("\n--- Δοκιμή 6: Έγκυρη εντολή (application/pdf) ---");
        mailcapSimulator.findAndExecuteMatch("application/pdf", "/tmp/document.pdf");
        // Δημιουργήστε ένα αρχείο /tmp/document.pdf
    }
}
