import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Simuliert die Funktion mailcap.findmatch. 
     * Konstruiert einen Befehl, um die Datei basierend auf dem mime_type anzuzeigen, und führt ihn aus.
     * 
     * Diese Implementierung enthält eine Überprüfung, um das Verketten von Befehlen zu verhindern, indem Semikolons blockiert werden.
     *
     * @param mimeType Der MIME-Typ der Datei.
     * @param filePath Der Pfad zur Datei, die angezeigt werden soll.
     * @return Der Exit-Code des ausgeführten Befehls.
     * @throws IOException Wenn ein E/A-Fehler auftritt.
     * @throws InterruptedException Wenn der aktuelle Thread unterbrochen wird, während er auf den Abschluss des Befehls wartet.
     */
    public int findAndExecuteMatch(String mimeType, String filePath) throws IOException, InterruptedException {
        // Basic sanitization to prevent command injection via semicolon
        // This is a simplistic check and might not cover all edge cases or shell variations.
        // A more robust solution might involve whitelisting allowed characters or using a dedicated command execution library.
        if (mimeType.contains(";") || filePath.contains(";")) {
            System.err.println("Fehler: Semikolons sind in MIME-Typ oder Dateipfad nicht erlaubt, um Befehlsverkettung zu verhindern.");
            return -1; // Indicate an error due to blocked characters
        }

        String command;

        // Simplified logic to determine the command based on mimeType
        // In a real mailcap implementation, this would involve parsing a mailcap file
        // and looking up the appropriate viewer command.
        if (mimeType.startsWith("image/")) {
            command = "xdg-open " + filePath; // Common for opening files on Linux desktops
        } else if (mimeType.startsWith("text/")) {
            command = "less " + filePath; // A common text viewer
        } else if (mimeType.startsWith("application/pdf")) {
            command = "xdg-open " + filePath; // For PDFs
        } else {
            System.err.println("Kein bekannter Viewer für MIME-Typ: " + mimeType);
            return -1; // No suitable viewer found
        }

        System.out.println("Führe Befehl aus: " + command);

        Process process = Runtime.getRuntime().exec(command);

        // Optional: Capture and print command output/errors
        // This helps in debugging what the external command is doing
        new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println("[STDOUT] " + line);
                }
            } catch (IOException e) {
                System.err.println("Fehler beim Lesen von STDOUT: " + e.getMessage());
            }
        }).start();

        new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.err.println("[STDERR] " + line);
                }
            } catch (IOException e) {
                System.err.println("Fehler beim Lesen von STDERR: " + e.getMessage());
            }
        }).start();

        // Wait for the command to complete and get its exit code
        int exitCode = process.waitFor();
        System.out.println("Befehl beendet mit Exit-Code: " + exitCode);
        return exitCode;
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();

        try {
            // Test cases
            System.out.println("\n--- Test 1: Image file ---");
            classX.findAndExecuteMatch("image/png", "/tmp/test_image.png"); // Replace with an actual image path

            System.out.println("\n--- Test 2: Text file ---");
            classX.findAndExecuteMatch("text/plain", "/tmp/test_document.txt"); // Replace with an actual text file path

            System.out.println("\n--- Test 3: PDF file ---");
            classX.findAndExecuteMatch("application/pdf", "/tmp/test.pdf"); // Replace with an actual PDF path

            System.out.println("\n--- Test 4: Unknown MIME type ---");
            classX.findAndExecuteMatch("application/x-unknown", "/tmp/unknown.dat");

            System.out.println("\n--- Test 5: Command Injection Attempt (semicolon in filePath) ---");
            classX.findAndExecuteMatch("text/plain", "/tmp/malicious.txt; rm -rf /");

            System.out.println("\n--- Test 6: Command Injection Attempt (semicolon in mimeType) ---");
            classX.findAndExecuteMatch("image/png; echo HACKED > /tmp/hacked.txt", "/tmp/image.png");

            // Create dummy files for testing if they don't exist
            // Note: This part is for convenience to make tests runnable.
            // In a real scenario, these files would already exist.
            createDummyFile("/tmp/test_image.png", "image");
            createDummyFile("/tmp/test_document.txt", "text");
            createDummyFile("/tmp/test.pdf", "pdf");

        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    // Helper method to create dummy files for testing purposes
    private static void createDummyFile(String path, String type) {
        java.io.File file = new java.io.File(path);
        if (!file.exists()) {
            try {
                if (type.equals("image")) {
                    // Create a very basic (invalid) PNG header to make it a "file"
                    java.nio.file.Files.write(file.toPath(), new byte[]{(byte) 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A});
                } else if (type.equals("text")) {
                    java.nio.file.Files.write(file.toPath(), "Dies ist ein Testdokument.\nEs enthält einige Zeilen Text.".getBytes());
                } else if (type.equals("pdf")) {
                    // Create a very basic (invalid) PDF header to make it a "file"
                    java.nio.file.Files.write(file.toPath(), "%PDF-1.4\n1 0 obj <</Type/Catalog/Pages 2 0 R>> endobj".getBytes());
                }
                System.out.println("Dummy-Datei erstellt: " + path);
            } catch (IOException e) {
                System.err.println("Fehler beim Erstellen der Dummy-Datei " + path + ": " + e.getMessage());
            }
        }
    }
}
