    /**
     * Simuliert die Funktion mailcap.findmatch.
     * Konstruiert einen Befehl, um die Datei basierend auf dem mime_type anzuzeigen, und führt ihn aus.
     *
     * Diese Implementierung enthält eine Überprüfung, um das Verketten von Befehlen zu verhindern, indem Semikolons blockiert werden.
     *
     * @param mimeType Der MIME-Typ der Datei (z.B. "text/plain", "image/jpeg").
     * @param filePath Der Pfad zur anzuzeigenden Datei.
     * @return Der Output des ausgeführten Befehls, oder eine Fehlermeldung bei Problemen.
     */
    public String findAndExecuteMatch(String mimeType, String filePath) {
        // Basic validation: Prevent command injection via semicolons
        if (mimeType == null || mimeType.contains(";") || filePath == null || filePath.contains(";")) {
            return "Error: Invalid input. Semicolons are not allowed to prevent command injection.";
        }

        // In a real mailcap.findmatch, you would parse mailcap files
        // to find the appropriate command. For this simulation, we'll
        // use a simplified mapping or a default viewer.

        String command = "";
        switch (mimeType) {
            case "text/plain":
                // Using 'cat' for text files as a simple viewer
                command = "cat " + filePath;
                break;
            case "image/jpeg":
            case "image/png":
                // Using 'xdg-open' for images (common on Linux desktops)
                // On Windows, 'start' could be used, on macOS 'open'
                command = "xdg-open " + filePath;
                break;
            case "application/pdf":
                command = "xdg-open " + filePath;
                break;
            default:
                // Fallback for unknown types
                command = "xdg-open " + filePath; // Try xdg-open as a general handler
                break;
        }

        if (command.isEmpty()) {
            return "Error: No suitable command found for MIME type: " + mimeType;
        }

        StringBuilder output = new StringBuilder();
        try {
            // Execute the command
            Process process = Runtime.getRuntime().exec(command);

            // Read the output from the command
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Read any errors from the command
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            String errorLine;
            while ((errorLine = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(errorLine).append("\n");
            }

            // Wait for the process to complete and get its exit value
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                output.append("Command exited with code: ").append(exitCode).append("\n");
            }

        } catch (IOException e) {
            return "Error executing command: " + e.getMessage();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            return "Error: Command execution was interrupted: " + e.getMessage();
        }

        return output.toString();
    }

