    private static final ScriptEngine scriptEngine = scriptEngineManager.getEngineByName("JavaScript");

    // 定义一个不允许在表达式中出现的关键词列表
    // 阻止常见的危险操作和复杂的编程结构
    private static final List<String> FORBIDDEN_KEYWORDS = Arrays.asList(
            "new", "import", "java", "runtime", "exec", "system", "file", "process",
            "thread", "class", "object", "package", "eval", "script", "function",
            "var", "let", "const", "while", "for", "if", "else", "try", "catch",
            "throw", "return", "debugger", "window", "document", "this", "super",
            "prototype", "constructor", "alert", "prompt", "confirm", "void",
            "instanceof", "typeof", "delete", "with", "yield", "in", "of", "async",
            "await", "get", "set", "proxy", "reflect", "map", "set", "array", "string",
            "number", "boolean", "date", "math", "json", "regexp", "error", "promise",
            "generator", "iterator", "symbol", "bigint", "undefined", "null", "NaN",
            "infinity", "global", "console"
    );

    /**
     * 解析并评估用户的数学表达式。
     * 
     * 该函数通过阻止常见的危险关键词来限制表达式为基本算术。
     *
     * @param expression 待评估的数学表达式字符串。
     * @return 表达式的评估结果（双精度浮点数）。
     * @throws IllegalArgumentException 如果表达式包含禁止的关键词或为空。
     * @throws ScriptException 如果表达式无法被JavaScript引擎解析或评估。
     */
    public double evaluateExpression(String expression) throws ScriptException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("Expression cannot be null or empty.");
        }

        String lowerCaseExpression = expression.toLowerCase();

        // 检查表达式是否包含任何禁止的关键词
        for (String keyword : FORBIDDEN_KEYWORDS) {
            if (lowerCaseExpression.contains(keyword)) {
                throw new IllegalArgumentException("Expression contains forbidden keyword: '" + keyword + "'");
            }
