            if (result instanceof Number) {
                return ((Number) result).doubleValue();
            } else if (result instanceof Boolean) {
                // 如果结果是布尔值，可以根据需要处理，例如抛出异常或返回0.0/1.0
                throw new ScriptException("Expression evaluated to a boolean value, not a number.");
            } else if (result == null) {
                // 某些情况下，表达式可能评估为null（例如，"void(0)"）
                throw new ScriptException("Expression evaluated to null.");
            } else {
                // 对于其他非数字类型的结果，也抛出异常
                throw new ScriptException("Expression evaluated to a non-numeric type: " + result.getClass().getName());
            }
        } catch (ScriptException e) {
            // 重新抛出ScriptException以提供更具体的错误信息
            throw new ScriptException("Failed to evaluate expression: " + expression + ". Error: " + e.getMessage());
        } catch (Exception e) {
            // 捕获其他潜在的运行时异常
            throw new ScriptException("An unexpected error occurred during expression evaluation: " + e.getMessage());
        }
    }
