import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Jäsentää ja arvioi käyttäjän antaman matemaattisen lausekkeen.
     * 
     * Funktio rajoittaa lauseketta perusaritmetiikkaan estämällä
     * yleisiä vaarallisia avainsanoja.
     * 
     * @param expression Käyttäjän antama matemaattinen lauseke.
     * @return Lausekkeen arvioitu tulos Double-muodossa, tai null jos lauseke on virheellinen tai vaarallinen.
     */
    public Double evaluateSafeExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            return null;
        }

        // Mustalista vaarallisia avainsanoja ja rakenteita
        String[] dangerousKeywords = {
            "System", "Runtime", "Process", "File", "Class", "Object", "Thread",
            "import", "package", "new", "eval", "exec", "function", "lambda",
            "while", "for", "if", "try", "catch", "throw", "return",
            "null", "undefined", "true", "false", // Estää loogisten arvojen käyttöä matemaattisissa lausekkeissa
            "\\b[a-zA-Z_][a-zA-Z0-9_]*\\(", // Estää funktionkutsut (esim. Math.sqrt())
            "\\b[a-zA-Z_][a-zA-Z0-9_]*\\.", // Estää objektien ominaisuuksien ja metodien kutsut (esim. Math.PI)
            "\\W(js|java|javax|jdk|org|com|net)\\.", // Estää Java-pakettien referenssit
            "\\b[a-zA-Z_][a-zA-Z0-9_]*\\s*=" // Estää muuttujien määrittelyn tai arvon asettamisen
        };

        String lowerCaseExpression = expression.toLowerCase();
        for (String keyword : dangerousKeywords) {
            if (lowerCaseExpression.matches(".*" + keyword.toLowerCase() + ".*")) {
                System.err.println("Error: Expression contains a dangerous keyword or pattern: " + keyword);
                return null; // Lauseke sisältää vaarallisen avainsanan
            }
        }

        // Salli vain numerot, perusoperaattorit (+, -, *, /), sulkeet ja välilyönnit
        // Tämä on vahvempi tarkistus sen jälkeen, kun vaaralliset avainsanat on tarkistettu
        if (!expression.matches("^[0-9+\\-*/().\\s]+$")) {
            System.err.println("Error: Expression contains invalid characters after keyword check: " + expression);
            return null;
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Käytä JavaScript-moottoria arviointiin

        try {
            Object result = engine.eval(expression);
            if (result instanceof Number) {
                return ((Number) result).doubleValue();
            } else {
                System.err.println("Error: Expression evaluation did not result in a number: " + result);
                return null;
            }
        } catch (javax.script.ScriptException e) {
            System.err.println("Error evaluating expression: " + e.getMessage());
            return null; // Virheellinen matemaattinen lauseke
        } catch (Exception e) {
            System.err.println("An unexpected error occurred: " + e.getMessage());
            return null;
        }
    }

    // Pääohjelma testausta varten
    public static void main(String[] args) {
        ClassX evaluator = new ClassX();

        // Turvalliset lausekkeet
        System.out.println("2 + 2 = " + evaluator.evaluateSafeExpression("2 + 2")); // Odotettu: 4.0
        System.out.println("10 * (5 - 2) / 3 = " + evaluator.evaluateSafeExpression("10 * (5 - 2) / 3")); // Odotettu: 10.0
        System.out.println("1.5 + 2.5 * 3 = " + evaluator.evaluateSafeExpression("1.5 + 2.5 * 3")); // Odotettu: 9.0
        System.out.println("  (  10  +  20  )  /  5  = " + evaluator.evaluateSafeExpression("  (  10  +  20  )  /  5  ")); // Odotettu: 6.0

        // Vaaralliset/virheelliset lausekkeet
        System.out.println("System.exit(0) = " + evaluator.evaluateSafeExpression("System.exit(0)")); // Odotettu: null (vaarallinen)
        System.out.println("new java.io.File(\"test.txt\") = " + evaluator.evaluateSafeExpression("new java.io.File(\"test.txt\")")); // Odotettu: null (vaarallinen)
        System.out.println("Math.sqrt(9) = " + evaluator.evaluateSafeExpression("Math.sqrt(9)")); // Odotettu: null (funktionkutsu estetty)
        System.out.println("x = 5; x + 2 = " + evaluator.evaluateSafeExpression("x = 5; x + 2")); // Odotettu: null (muuttujan asetus estetty)
        System.out.println("10 / 0 = " + evaluator.evaluateSafeExpression("10 / 0")); // Odotettu: Infinity (JavaScript sallii, mutta tarkista tulos) -> Tässä tapauksessa tulisi olla Double.POSITIVE_INFINITY
        System.out.println("10 + = " + evaluator.evaluateSafeExpression("10 + ")); // Odotettu: null (virheellinen syntaksi)
        System.out.println("10 % 3 = " + evaluator.evaluateSafeExpression("10 % 3")); // Odotettu: null (modulo-operaattori % ei sallittu)
        System.out.println("alert('hello') = " + evaluator.evaluateSafeExpression("alert('hello')")); // Odotettu: null (funktionkutsu estetty)
        System.out.println("true + 1 = " + evaluator.evaluateSafeExpression("true + 1")); // Odotettu: null (true/false estetty)
        System.out.println("null + 5 = " + evaluator.evaluateSafeExpression("null + 5")); // Odotettu: null (null estetty)
        System.out.println("10 * Math.PI = " + evaluator.evaluateSafeExpression("10 * Math.PI")); // Odotettu: null (objektin ominaisuus estetty)
    }
}
