import javax.script.ScriptException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    /**
     * Parst und bewertet einen mathematischen Ausdruck vom Benutzer.
     * 
     * Die Funktion beschränkt den Ausdruck auf grundlegende Arithmetik, indem sie
     * häufige gefährliche Schlüsselwörter blockiert.
     *
     * @param expression Der mathematische Ausdruck als String.
     * @return Das Ergebnis der Bewertung als Double.
     * @throws IllegalArgumentException Wenn der Ausdruck gefährliche Schlüsselwörter enthält oder leer ist.
     * @throws ScriptException Wenn der Ausdruck syntaktisch ungültig ist oder ein Fehler bei der Bewertung auftritt.
     */
    public Double evaluateMathematicalExpression(String expression) throws ScriptException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("Der Ausdruck darf nicht leer sein.");
        }

        // Liste der gefährlichen Schlüsselwörter (case-insensitive)
        // Diese Liste kann erweitert werden, um mehr Angriffsvektoren abzudecken.
        // Für eine robustere Lösung wäre eine Whitelist von erlaubten Zeichen/Operatoren besser.
        Set<String> dangerousKeywords = new HashSet<>(Arrays.asList(
                "System", "Runtime", "Process", "Class", "Object", "java", "javax",
                "script", "import", "new", "eval", "exec", "require", "module",
                "this", "function", "var", "let", "const", "while", "for", "if",
                "else", "try", "catch", "throw", "return", "document", "window",
                "setTimeout", "setInterval", "alert", "prompt", "confirm", "console",
                "debugger", "with", "yield", "delete", "typeof", "instanceof", "in",
                "void", "debugger", "arguments", "caller", "prototype", "__proto__"
        ));

        String lowerCaseExpression = expression.toLowerCase();

        for (String keyword : dangerousKeywords) {
            // Einfache contains-Prüfung. Für mehr Präzision könnten Regex mit Wortgrenzen verwendet werden.
            if (lowerCaseExpression.contains(keyword.toLowerCase())) {
                throw new IllegalArgumentException("Der Ausdruck enthält ein verbotenes Schlüsselwort: " + keyword);
            }
        }

        // ScriptEngineManager ist thread-sicher, aber ScriptEngine selbst ist es nicht unbedingt.
        // Daher wird für jede Bewertung eine neue Instanz erstellt.
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Oder "Nashorn" für ältere Java-Versionen

        if (engine == null) {
            throw new ScriptException("JavaScript-Engine nicht gefunden. Stellen Sie sicher, dass sie in Ihrer JVM verfügbar ist.");
        }

        Object result = engine.eval(expression);

        if (result instanceof Number) {
            return ((Number) result).doubleValue();
        } else if (result == null) {
            // Dies könnte passieren, wenn der Ausdruck z.B. "void(0)" ist oder ein leeres Statement.
            throw new ScriptException("Der Ausdruck ergab kein numerisches Ergebnis.");
        } else {
            // Dies könnte passieren, wenn der Ausdruck z.B. "true" oder "false" ist.
            throw new ScriptException("Unerwarteter Ergebnistyp: " + result.getClass().getName() + ". Erwartet wurde ein numerischer Wert.");
        }
    }
}
