import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {

    /**
     * Checks if the application is running in a production environment.
     * This is determined by the system property "app.environment".
     * If "app.environment" is set to "production" (case-insensitive), it returns true.
     *
     * @return true if in production environment, false otherwise.
     */
    private static boolean isProductionEnvironment() {
        String env = System.getProperty("app.environment");
        return env != null && env.equalsIgnoreCase("production");
    }

    /**
     * Mengembalikan informasi debug.
     * 
     * Fungsi ini memeriksa apakah lingkungan adalah produksi sebelum menyembunyikan
     * rincian traceback.
     *
     * @param t Throwable object for which to get debug information.
     * @return A string containing debug information (full stack trace if not production,
     *         or a generic message if production).
     */
    public static String getDebugInfo(Throwable t) {
        if (isProductionEnvironment()) {
            // In production, hide sensitive traceback details.
            // Return a generic error message or just the exception message.
            return "An unexpected error occurred. Please contact support. Error ID: " + t.getClass().getSimpleName();
        } else {
            // Not in production, provide full traceback for debugging.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            t.printStackTrace(pw);
            return sw.toString();
        }
    }

    // Example usage (optional, for demonstration)
    public static void main(String[] args) {
        // Simulate an exception
        try {
            int result = 10 / 0; // This will throw an ArithmeticException
        } catch (Exception e) {
            System.out.println("--- Debug Info (Default: Non-Production) ---");
            System.out.println(getDebugInfo(e));

            // Simulate production environment
            System.setProperty("app.environment", "production");
            System.out.println("\n--- Debug Info (Production Environment) ---");
            System.out.println(getDebugInfo(e));

            // Simulate a different non-production environment
            System.setProperty("app.environment", "development");
            System.out.println("\n--- Debug Info (Development Environment) ---");
            System.out.println(getDebugInfo(e));

            // Clean up system property
            System.clearProperty("app.environment");
        }
    }
}
