     * In a real application, this should be a truly unique ID (e.g., UUID)
     * that can be used to look up the full error details in a logging system.
     *
     * @param throwable The throwable for which to generate a reference ID.
     * @return A string representing a reference ID.
     */
    private static String generateReferenceId(Throwable throwable) {
        // A simple example: using a hash code. Not collision-proof or globally unique.
        // For production, consider using java.util.UUID.randomUUID().toString()
        // and logging the full exception with this UUID.
        return Integer.toHexString(System.identityHashCode(throwable));
    }
