import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Devuelve información de depuración para una excepción dada.
     * <p>
     * La función verifica si el entorno es de producción (basado en la propiedad del sistema "env.production")
     * antes de suprimir los detalles del seguimiento de pila.
     * Si {@code -Denv.production=true} está configurado, se devuelve un mensaje genérico.
     * En caso contrario, se incluye el seguimiento de pila completo.
     * </p>
     *
     * @param throwable La excepción o error para el cual se necesita la información de depuración.
     * @return Una cadena que contiene la información de depuración. Incluye el seguimiento de pila
     *         si el entorno no es de producción, o un mensaje genérico si lo es.
     */
    public static String getDebugInfo(Throwable throwable) {
        // La propiedad del sistema "env.production" puede ser configurada con -Denv.production=true
        // al iniciar la JVM para indicar un entorno de producción.
        boolean isProduction = "true".equalsIgnoreCase(System.getProperty("env.production"));

        if (isProduction) {
            // En un entorno de producción, se devuelve un mensaje genérico para evitar exponer
            // detalles internos sensibles o información de la estructura del sistema.
            return "Ocurrió un error inesperado. Por favor, intente de nuevo más tarde o contacte al soporte. " +
                   "Mensaje de error: " + (throwable != null ? throwable.getMessage() : "N/A");
        } else {
            // En entornos que no son de producción (desarrollo, pruebas, staging),
            // se incluye el seguimiento de pila completo para facilitar la depuración.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            if (throwable != null) {
                throwable.printStackTrace(pw);
            } else {
                pw.println("No se proporcionó ninguna excepción.");
            }
            return "Detalles de depuración (entorno NO de producción):\n" + sw.toString();
        }
    }
}
