import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {

    /**
     * Determina si el entorno actual es de producción.
     * Esta propiedad se puede configurar a través de un parámetro del sistema JVM, por ejemplo:
     * -Dapp.env.production=true
     * Si no se especifica, se asume que no es producción (false).
     */
    private static final boolean IS_PRODUCTION = Boolean.parseBoolean(System.getProperty("app.env.production", "false"));

    /**
     * Devuelve información de depuración.
     *
     * La función verifica si el entorno es de producción antes de suprimir los detalles del seguimiento.
     * En un entorno de producción, solo se proporciona un mensaje general y el mensaje de la excepción,
     * sin el seguimiento completo de la pila. En entornos que no son de producción,
     * se incluye el seguimiento completo de la pila.
     *
     * @param throwable La excepción o error para el cual se generará la información de depuración.
     *                  Puede ser {@code null} si no hay una excepción específica.
     * @return Una cadena que contiene información de depuración, con o sin detalles de seguimiento
     *         según el entorno configurado.
     */
    public static String getDebugInfo(Throwable throwable) {
        StringBuilder debugInfo = new StringBuilder();
        debugInfo.append("--- Información de Depuración ---\n");
        debugInfo.append("Entorno: ").append(IS_PRODUCTION ? "Producción" : "Desarrollo/Pruebas").append("\n");

        if (throwable != null) {
            debugInfo.append("Tipo de Error: ").append(throwable.getClass().getName()).append("\n");
            debugInfo.append("Mensaje: ").append(throwable.getMessage() != null ? throwable.getMessage() : "[Sin mensaje]").append("\n");

            if (!IS_PRODUCTION) {
                // En entornos que no son de producción, incluimos el seguimiento completo de la pila.
                debugInfo.append("Detalles del Seguimiento de Pila:\n");
                StringWriter sw = new StringWriter();
                PrintWriter pw = new PrintWriter(sw);
                throwable.printStackTrace(pw);
                debugInfo.append(sw.toString());
            } else {
                // En producción, solo proporcionamos un mensaje general para evitar exponer detalles internos.
                debugInfo.append("Detalles del error suprimidos para el entorno de producción.\n");
                debugInfo.append("Por favor, póngase en contacto con el soporte técnico para más información.\n");
            }
        } else {
            debugInfo.append("No se proporcionó ninguna excepción específica.\n");
        }

        debugInfo.append("---------------------------------\n");
        return debugInfo.toString();
    }
}
