import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {

    private static final String ENVIRONMENT_PROPERTY_KEY = "app.env";
    private static final String PRODUCTION_ENVIRONMENT_VALUE = "production";

    /**
     * Nagbabalik ng impormasyon sa pag-debug.
     *
     * Sinusuri ng function kung ang kapaligiran ay production bago itago ang mga detalye ng traceback.
     *
     * @param message Ang mensahe ng debug na ipapakita.
     * @param throwable Ang Throwable object na maaaring naglalaman ng stack trace (opsyonal).
     * @return Isang string na naglalaman ng impormasyon sa pag-debug.
     */
    public String getDebugInfo(String message, Throwable throwable) {
        StringBuilder debugInfo = new StringBuilder();
        debugInfo.append("Debug Message: ").append(message);

        if (throwable != null) {
            if (isProductionEnvironment()) {
                // Sa production environment, ilabas lamang ang uri at mensahe ng error.
                // Itago ang buong stack trace para sa seguridad at kalinisan.
                debugInfo.append("\nError Type: ").append(throwable.getClass().getName());
                debugInfo.append("\nError Cause: ").append(throwable.getMessage());
            } else {
                // Sa non-production environment, isama ang buong stack trace.
                debugInfo.append("\nStack Trace:\n");
                StringWriter sw = new StringWriter();
                PrintWriter pw = new PrintWriter(sw);
                throwable.printStackTrace(pw);
                debugInfo.append(sw.toString());
            }
        }

        return debugInfo.toString();
    }

    /**
     * Nagbabalik ng impormasyon sa pag-debug nang walang kasamang Throwable.
     *
     * @param message Ang mensahe ng debug na ipapakita.
     * @return Isang string na naglalaman ng impormasyon sa pag-debug.
     */
    public String getDebugInfo(String message) {
        return getDebugInfo(message, null);
    }

    /**
     * Sinusuri kung ang kasalukuyang kapaligiran ay production.
     * Ginagamit ang system property na "app.env". Halimbawa: -Dapp.env=production
     *
     * @return true kung ang kapaligiran ay production, false kung hindi.
     */
    private boolean isProductionEnvironment() {
        String env = System.getProperty(ENVIRONMENT_PROPERTY_KEY);
        return PRODUCTION_ENVIRONMENT_VALUE.equalsIgnoreCase(env);
    }
}

