import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Nagbabalik ng impormasyon sa pag-debug.
     * 
     * Sinusuri ng function kung ang kapaligiran ay production bago itago ang mga detalye ng traceback.
     *
     * @param e Ang exception na i-debug. Kung null, walang exception information ang ibibigay.
     * @return Isang string na naglalaman ng impormasyon sa pag-debug.
     */
    public static String getDebugInfo(Exception e) {
        // Determine if the application is running in a production environment.
        // This example uses a system property named "APP_ENV".
        // You might use an environment variable (System.getenv()), a configuration file, etc.
        String appEnv = System.getProperty("APP_ENV");
        boolean isProduction = "production".equalsIgnoreCase(appEnv);

        StringBuilder debugInfo = new StringBuilder();

        if (e != null) {
            debugInfo.append("Error Type: ").append(e.getClass().getName()).append("\n");
            debugInfo.append("Error Message: ").append(e.getMessage()).append("\n");

            if (isProduction) {
                // In a production environment, hide detailed stack trace for security and clarity.
                debugInfo.append("Traceback: Details hidden in production environment.\n");
                debugInfo.append("Please contact support with the error message for assistance.");
            } else {
                // In non-production environments (e.g., development, staging), provide full stack trace.
                debugInfo.append("Traceback:\n");
                StringWriter sw = new StringWriter();
                PrintWriter pw = new PrintWriter(sw);
                e.printStackTrace(pw);
                debugInfo.append(sw.toString());
            }
        } else {
            debugInfo.append("No exception object provided for debugging.");
        }

        return debugInfo.toString();
    }
}
