            return "No exception provided.";
        }

        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);
        t.printStackTrace(pw);
        String stackTrace = sw.toString();

        if (isProductionEnvironment()) {
            // Tootmiskeskkonnas tagastame üldisema sõnumi ilma virna jälgimise detailideta
            return "An error occurred. Please contact support. Error type: " + t.getClass().getName() + ", Message: " + t.getMessage();
