import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Restituisce informazioni di debug per un'eccezione data.
     * <p>
     * La funzione verifica se l'ambiente è in produzione prima di sopprimere i dettagli del traceback.
     * In ambiente di produzione, viene fornito un messaggio generico per evitare di esporre dettagli sensibili.
     * In ambiente di sviluppo/test, viene incluso il traceback completo dell'eccezione.
     *
     * @param e L'eccezione per cui generare le informazioni di debug.
     * @param isProduction {@code true} se l'applicazione è in esecuzione in un ambiente di produzione; {@code false} altrimenti.
     * @return Una stringa contenente le informazioni di debug appropriate per l'ambiente specificato.
     */
    public String getDebugInfo(Exception e, boolean isProduction) {
        if (e == null) {
            return "Nessuna eccezione fornita.";
        }

        if (!isProduction) {
            // Ambiente di sviluppo/test: includi il traceback completo
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            e.printStackTrace(pw);
            pw.flush(); // Assicura che tutto sia scritto nello StringWriter
            return "Dettagli di debug (Ambiente non di produzione):\n" + sw.toString();
        } else {
            // Ambiente di produzione: fornisci un messaggio generico
            // Evita di esporre dettagli interni sensibili per motivi di sicurezza e usabilità.
            return "Si è verificato un errore interno. Si prega di riprovare più tardi. (Codice riferimento: " + e.getClass().getSimpleName() + ")";
            // In un'applicazione reale, qui si potrebbe anche loggare l'eccezione completa
            // con un logger (es. SLF4J, Log4j, java.util.logging)
            // e restituire all'utente solo un ID di riferimento per quella particolare occorrenza.
        }
    }
}
