            } else {
                return "Um erro inesperado ocorreu. Por favor, contate o suporte.";
            }
        } else {
            // Em ambientes de não produção (desenvolvimento, teste), fornece o traceback completo
            // para auxiliar na depuração.
            if (throwable != null) {
                StringWriter stringWriter = new StringWriter();
                PrintWriter printWriter = new PrintWriter(stringWriter);
                throwable.printStackTrace(printWriter);
                return stringWriter.toString();
            } else {
                return "Nenhuma exceção ou erro fornecido para depuração.";
