     * @param throwable L'exception ou l'erreur pour laquelle obtenir les informations de débogage.
     * @return Une chaîne de caractères contenant les informations de débogage.
     *         Si l'environnement est en production (déterminé par la propriété système "app.isProduction" à "true"),
     *         seul le message de l'exception est retourné. Sinon, la trace complète est retournée.
     */
    public String getDebugInfo(Throwable throwable) {
        // Vérifie si l'environnement est en production.
        // La propriété système "app.isProduction" peut être définie lors du démarrage de la JVM, par exemple :
        // java -Dapp.isProduction=true -jar votreApp.jar
        boolean isProduction = Boolean.parseBoolean(System.getProperty("app.isProduction", "false"));

        if (isProduction) {
            // En environnement de production, ne renvoyer que le message de l'exception pour éviter de divulguer des détails internes.
            return "Une erreur est survenue. Message: " + (throwable != null ? throwable.getMessage() : "Inconnu");
        } else {
            // En environnement de développement ou de test, renvoyer la trace complète de l'exception.
            if (throwable == null) {
                return "Aucune exception fournie pour le débogage.";
            }
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }
}
