        sanitizedInput = sanitizedInput.replaceAll("(?i)<script\\b[^>]*>", "");

        // Remove any unmatched closing script tags as well.
        sanitizedInput = sanitizedInput.replaceAll("(?i)</script>", "");

        return sanitizedInput;
