public class ClassX {
    /**
     * Schoont gebruikersinvoer op door script-tags te verwijderen.
     * 
     * De functie gebruikt stringvervanging om <script>-tags te verwijderen.
     * Dit omvat het verwijderen van de volledige script-blokken (inclusief inhoud)
     * en eventuele losse, niet-afgesloten script-tags.
     * De verwijdering is hoofdletterongevoelig.
     *
     * @param input De onbewerkte gebruikersinvoer.
     * @return De opgeschoonde invoer zonder script-tags.
     */
    public String sanitizeInput(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // 1. Verwijder volledige <script>...</script> blokken, inclusief inhoud
        // De regex is hoofdletterongevoelig (?i) en gebruikt non-greedy matching (.*?)
        // om ervoor te zorgen dat het de kortst mogelijke match vindt tussen <script> en </script>.
        // \b zorgt ervoor dat 'script' een heel woord is, om bijvoorbeeld 'javascript' niet te matchen.
        String cleanedInput = input.replaceAll("(?i)<script\\b[^>]*>.*?</script>", "");

        // 2. Verwijder eventuele losse of niet-afgesloten <script> tags
        // Dit vangt gevallen op waar een script-tag wel opent maar niet sluit,
        // of waar de sluit-tag ontbreekt na het verwijderen van een blok.
        cleanedInput = cleanedInput.replaceAll("(?i)<script\\b[^>]*>", "");

        return cleanedInput;
    }
}
