     * 
     * Fonksiyon, &lt;script&gt; etiketlerini çıkarmak için dize değiştirme kullanır.
     * Bu yöntem, &lt;script&gt; etiketlerinin kendisini ve içindeki içeriği kaldırarak
     * basit XSS (Cross-Site Scripting) saldırılarına karşı koruma sağlamayı amaçlar.
     *
     * @param input Temizlenecek kullanıcı girişi dizesi. Eğer giriş null veya boşsa, olduğu gibi döndürülür.
     * @return &lt;script&gt; etiketleri ve içerikleri kaldırılmış temizlenmiş dize.
     */
    public static String sanitizeInput(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // (?i) bayrağı, büyük/küçük harf duyarsız eşleşmeyi sağlar.
        // <script\\b[^>]*> ifadesi, "script" kelimesinden sonra bir kelime sınırı (\b) olan
        // ve herhangi bir öznitelik içerebilen açılış <script> etiketini eşleştirir.
        // [\\s\\S]*? ifadesi, boşluk karakterleri dahil tüm karakterleri (satır sonları dahil)
        // en az sayıda eşleştirir (non-greedy), bu da ilk kapanış </script> etiketine kadar eşleşmeyi sağlar.
        // </script> ifadesi, kapanış </script> etiketini eşleştirir.
        String scriptBlockRegex = "(?i)<script\\b[^>]*>[\\s\\S]*?<\\/script>";

        // Tüm script bloklarını (açılış, içerik, kapanış) kaldır.
        String sanitized = input.replaceAll(scriptBlockRegex, "");

        // Kalan tekil açılış <script> veya kapanış </script> etiketlerini de kaldır.
        // Bu, düzgün kapanmamış veya ayrık etiket durumlarını ele almak içindir.
        sanitized = sanitized.replaceAll("(?i)<script[^>]*>", "");
        sanitized = sanitized.replaceAll("(?i)</script>", "");

        return sanitized;
    }
}
