     */
    public String sanitizeInput(String input) {
        if (input == null) {
            return null;
        }

        // Χρησιμοποιούμε regular expressions για την αφαίρεση των ετικετών <script> και </script>.
        // Η σημαία "(?i)" κάνει την αντικατάσταση case-insensitive.
        // Το "\\b" εξασφαλίζει ότι ταιριάζουμε μόνο την λέξη "script" και όχι π.χ. "javascript".
        // Το "[^>]*" ταιριάζει οποιοδήποτε χαρακτήρα εκτός από ">" μηδέν ή περισσότερες φορές,
        // καλύπτοντας έτσι τυχόν χαρακτηριστικά μέσα στην ετικέτα <script> (π.χ. <script src="...">).

        // Αφαίρεση των ετικετών έναρξης <script ...>
        String sanitized = input.replaceAll("(?i)<script\\b[^>]*>", "");

        // Αφαίρεση των ετικετών λήξης </script>
        sanitized = sanitized.replaceAll("(?i)</script>", "");

        return sanitized;
    }
}
