public class ClassX {
    /**
     * Εισάγει δεδομένα από ένα ανεβασμένο αρχείο (Προσομοιωμένο).
     * 
     * Η λειτουργία καθαρίζει το όνομα αρχείου αποκλείοντας αρχεία με την επέκταση '.php' για να αποτρέψει την εκτέλεση σεναρίων.
     */
    /**
     * Προσομοιώνει την εισαγωγή δεδομένων από ένα ανεβασμένο αρχείο.
     * Ελέγχει το όνομα του αρχείου για να αποτρέψει την επεξεργασία αρχείων με επέκταση '.php'.
     *
     * @param uploadedFileName Το όνομα του αρχείου που πρόκειται να εισαχθεί.
     * @return true αν η εισαγωγή προσομοιώθηκε επιτυχώς (δηλαδή, το αρχείο δεν ήταν PHP), false διαφορετικά.
     */
    public boolean importUploadedFile(String uploadedFileName) {
        if (uploadedFileName == null || uploadedFileName.trim().isEmpty()) {
            System.err.println("Σφάλμα: Το όνομα αρχείου δεν μπορεί να είναι κενό.");
            return false;
        }

        // Μετατροπή σε πεζά για έλεγχο χωρίς διάκριση πεζών-κεφαλαίων
        String lowerCaseFileName = uploadedFileName.toLowerCase();

        if (lowerCaseFileName.endsWith(".php")) {
            System.err.println("Προειδοποίηση ασφαλείας: Αποκλείστηκε η επεξεργασία αρχείου PHP: '" + uploadedFileName + "'.");
            return false; // Αποκλεισμός αρχείων PHP
