public class ClassX {
    /**
     * Yüklenen bir dosyadan veri alır (Simüle Edilmiş).
     *
     * Fonksiyon, '.php' uzantısına sahip dosyaları engelleyerek dosya adını temizler ve böylece betik çalıştırılmasını önler.
     *
     * @param file İşlenecek dosya nesnesi.
     * @return Dosyanın içeriğini temsil eden bir String. Güvenlik kontrolünden geçemezse boş bir String döner.
     * @throws IllegalArgumentException Eğer dosya adı '.php' uzantısına sahipse.
     * @throws IOException Dosya okuma sırasında bir hata oluşursa.
     */
    public String getDataFromFile(File file) throws IOException {
        if (file == null) {
            return ""; // Or throw NullPointerException
        }

        String fileName = file.getName();

        // Güvenlik kontrolü: .php uzantılı dosyaları engelle
        if (fileName.toLowerCase().endsWith(".php")) {
            throw new IllegalArgumentException("Güvenlik ihlali: '.php' uzantılı dosyalara izin verilmiyor.");
        }

        // Dosya adını temizleme (örneğin yol manipülasyonlarını engellemek için)
        // Bu örnekte, sadece güvenli uzantıyı kontrol ettik. Daha karmaşık temizleme gerekebilir.
        String cleanedFileName = fileName.replaceAll("[^a-zA-Z0-9.\\-_]", "");

        // Simüle edilmiş veri okuma
        // Gerçek bir uygulamada, dosya içeriği buradan okunur.
        // Bu örnekte, sadece dosyanın varlığını kontrol edip bir mesaj döndürüyoruz.
        if (file.exists() && file.isFile()) {
            // Gerçek dosya içeriğini okuma örneği (basit bir metin dosyası olduğunu varsayarak)
            try {
                return new String(Files.readAllBytes(Paths.get(file.getAbsolutePath())));
            } catch (IOException e) {
                // Dosya okuma hatası durumunda
                throw new IOException("Dosya okunurken bir hata oluştu: " + cleanedFileName, e);
            }
        } else {
            return "Dosya bulunamadı veya geçerli bir dosya değil: " + cleanedFileName;
        }
    }
}
