     */
    private static final String HEADER_VALIDATION_REGEX = "^[a-zA-Z0-9 ]+$";
    private static final Pattern HEADER_VALIDATION_PATTERN = Pattern.compile(HEADER_VALIDATION_REGEX);

    /**
     * Validates the format of an HTTP header string.
     * This function uses a regular expression to ensure the header only contains
     * alphanumeric characters (a-z, A-Z, 0-9) and spaces.
     *
     * @param header The HTTP header string to be validated.
     * @return {@code true} if the header string conforms to the specified format; {@code false} otherwise.
     */
    public boolean isValidHeaderFormat(String header) {
        if (header == null) {
            return false; // A null header is not considered valid.
        }
        // The regex "^[a-zA-Z0-9 ]+$" inherently handles empty strings by not matching them.
        Matcher matcher = HEADER_VALIDATION_PATTERN.matcher(header);
        return matcher.matches();
    }
}
