    public String encrypt(String data, byte[] keyBytes) {
        try {
            String algorithm;
            if (keyBytes.length == 16) { // AES uses 16-byte (128-bit) keys
                algorithm = "AES";
            } else if (keyBytes.length == 8) { // DES uses 8-byte (64-bit) keys
                algorithm = "DES";
