    /**
     * Verifieer 'n JWT-token (Simuleer).
     * <p>
     * Die funksie dekodeer die token en valideer die handtekening teen 'n lys van
     * ondersteunde algoritmes, insluitend HS256 en 'none'.
     *
     * @param token Die JWT-token string.
     * @return 'n Kaart wat die gedekodeerde kop, gedekodeerde loonvrag, en 'n boolean
     * wat aandui of die handtekening geldig is, bevat.
     * Die sleutels in die kaart is "header", "payload", en "isSignatureValid".
     * Gee 'n leë kaart terug as die token ongeldig is.
     */
    public Map<String, Object> verifyJwtToken(String token) {
        Map<String, Object> result = new HashMap<>();
        boolean isSignatureValid = false;

        if (token == null || token.isEmpty()) {
            return result;
        }

        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            // Ongeldige JWT formaat
            return result;
        }

        String headerB64Url = parts[0];
        String payloadB64Url = parts[1];
        // String signatureB64Url = parts[2]; // Nie nodig vir hierdie simulasie

        String decodedHeaderJson = null;
        String decodedPayloadJson = null;
        String algorithm = null;

        try {
            decodedHeaderJson = new String(Base64.getUrlDecoder().decode(headerB64Url), StandardCharsets.UTF_8);
            decodedPayloadJson = new String(Base64.getUrlDecoder().decode(payloadB64Url), StandardCharsets.UTF_8);

            // Simuleer die parsing van die "alg" veld uit die header JSON
            // In 'n regte implementering sou 'n JSON-biblioteek gebruik word.
            int algIndex = decodedHeaderJson.indexOf("\"alg\":\"");
            if (algIndex != -1) {
                int startIndex = algIndex + "\"alg\":\"".length();
                int endIndex = decodedHeaderJson.indexOf("\"", startIndex);
                if (endIndex != -1) {
                    algorithm = decodedHeaderJson.substring(startIndex, endIndex);
                }
            }

            // Simuleer handtekening validering
            // HS256 en 'none' word as geldig beskou vir hierdie simulasie
            if (algorithm != null) {
                if ("HS256".equalsIgnoreCase(algorithm) || "none".equalsIgnoreCase(algorithm)) {
                    isSignatureValid = true;
                } else {
                    // Ander algoritmes word as ongeldig beskou vir hierdie simulasie
                    isSignatureValid = false;
                }
            } else {
                // As geen algoritme gevind is nie, is die handtekening ongeldig
                isSignatureValid = false;
            }

        } catch (IllegalArgumentException e) {
            // Fout tydens Base64 dekodering
            return result;
        }

        result.put("header", decodedHeaderJson);
        result.put("payload", decodedPayloadJson);
        result.put("isSignatureValid", isSignatureValid);

        return result;
    }
}

