            // về lỗi phân tích cú pháp hoặc phát hiện thẻ nguy hiểm.
            throw new YAMLException("Lỗi khi tải cấu hình YAML hoặc phát hiện thẻ nguy hiểm: " + e.getMessage(), e);
        }
    }
}

