import org.yaml.snakeyaml.constructor.SafeConstructor;
import org.yaml.snakeyaml.error.YAMLException;

public class ClassX {

    /**
     * Represents a simple configuration object that can be loaded from YAML.
     * For demonstration purposes, you would replace this with your actual configuration class.
     */
    public static class Config {
        public String name;
        public int value;

        // Default constructor is required for SnakeYAML to instantiate the object
        public Config() {
        }

        public Config(String name, int value) {
            this.name = name;
            this.value = value;
        }

        @Override
        public String toString() {
            return "Config{" +
                   "name='" + name + '\'' +
                   ", value=" + value +
                   '}';
        }
    }

    /**
     * 从 YAML 字符串加载配置。
     * 
     * 该函数检查显式的危险标签，以防止对象实例化。
     * 
     * @param yamlString 要加载的 YAML 字符串。
     * @return 加载的配置对象。
     * @throws YAMLException 如果 YAML 解析失败或包含危险标签。
     */
    public Config loadConfigFromYamlString(String yamlString) throws YAMLException {
        // 使用 SafeConstructor 来防止任意类的实例化，从而避免反序列化漏洞。
        // SafeConstructor 只允许加载基本的 Java 类型（String, Integer, List, Map等），
        // 并且不允许通过 !!java/object 或其他类似标签来实例化任意对象。
        // 如果需要自定义类型，但仍然要保持安全，可以继承 SafeConstructor 并覆盖其方法
        // 来明确允许某些特定的自定义类型，而不是所有类型。
        Yaml yaml = new Yaml(new SafeConstructor());

        // 使用 loadAs 方法将 YAML 字符串解析为指定类型的对象。
        // 如果 YAML 字符串包含 SafeConstructor 不允许的类型标签，
        // 则会抛出异常。
        try {
            return yaml.loadAs(yamlString, Config.class);
        } catch (YAMLException e) {
            // 捕获并重新抛出，或者根据需要进行更详细的错误处理。
            // 例如，可以检查 e.getMessage() 来判断是否是由于不允许的标签引起的。
            throw new YAMLException("Failed to load configuration from YAML string, possibly due to dangerous tags: " + e.getMessage(), e);
        }
    }

    // 示例用法 (可选，用于测试)
    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // 示例 1: 有效且安全的 YAML
        String safeYaml = "name: MyConfig\nvalue: 123";
        try {
            Config config = classX.loadConfigFromYamlString(safeYaml);
            System.out.println("Loaded safe config: " + config);
        } catch (YAMLException e) {
            System.err.println("Error loading safe config: " + e.getMessage());
        }

        // 示例 2: 包含危险标签的 YAML (尝试实例化任意类)
        // 这是一个常见的反序列化攻击向量
        String dangerousYaml = "!!java.lang.Runtime [ getRuntime ]";
        try {
            Config config = classX.loadConfigFromYamlString(dangerousYaml);
            System.out.println("Loaded dangerous config (SHOULD NOT HAPPEN): " + config);
        } catch (YAMLException e) {
            System.err.println("Successfully prevented dangerous config load: " + e.getMessage());
        }

        // 示例 3: 包含自定义类标签的 YAML (SafeConstructor 默认不允许)
        // 如果 Config 类没有在 SafeConstructor 中明确允许，这也会失败
        String customClassYaml = "!!org.example.MyCustomClass { field: value }"; // 假设 MyCustomClass 不存在或未被允许
        // 为了让这个例子更贴切，我们尝试用 Config 自己的标签，但 SafeConstructor 仍然会拒绝
        String configClassYaml = "!!ClassX$Config { name: Custom, value: 456 }";
        try {
            Config config = classX.loadConfigFromYamlString(configClassYaml);
            System.out.println("Loaded config with explicit tag (SHOULD NOT HAPPEN if not whitelisted): " + config);
        } catch (YAMLException e) {
            System.err.println("Successfully prevented config load with explicit class tag: " + e.getMessage());
        }
    }
}
