import org.yaml.snakeyaml.nodes.Tag;

public class ClassX {
    /**
     * Laadt configuratie vanuit een YAML-string.
     *
     * De functie controleert op expliciete gevaarlijke tags om objectinstantiatie te voorkomen.
     * Dit wordt gedaan door een {@link TagInspector} te implementeren die alle Java-specifieke tags blokkeert.
     *
     * @param yamlString De YAML-string om te laden.
     * @param type De klasse van het object waarin de YAML moet worden gedeserialiseerd.
     * @param <T> Het type van het object.
     * @return Een object van het opgegeven type, gevuld met de gegevens uit de YAML-string.
     * @throws YAMLException Als er een probleem is met het parseren of deserialiseren van de YAML,
     *                       inclusief het tegenkomen van een geblokkeerde tag.
     */
    public <T> T loadConfigFromString(String yamlString, Class<T> type) throws YAMLException {
        // Gebruik een Constructor die is ingesteld voor het verwachte type.
        // Dit helpt bij het beperken van de typen die kunnen worden gemaakt.
        Constructor constructor = new Constructor(type);

        // Stel een TagInspector in om expliciete gevaarlijke tags te blokkeren.
        // De meest voorkomende gevaarlijke tags beginnen met "tag:yaml.org,2002:java.".
        // Door deze te blokkeren, wordt voorkomen dat willekeurige Java-objecten worden geïnstantieerd.
        constructor.setTagInspector(new TagInspector() {
            @Override
            public boolean isTagAllowed(Tag tag) {
                // Blokkeer alle tags die beginnen met het standaard Java-tagprefix.
                // Dit is een robuuste maatregel om deserialisatie van willekeurige Java-klassen te voorkomen.
                if (tag.startsWith(Tag.PREFIX + "java.")) {
                    return false; // Blokkeer de tag
                }
                // Sta alle andere tags toe (standaard YAML-typen, etc.).
                return true;
            }
        });

        Yaml yaml = new Yaml(constructor);
        return yaml.loadAs(yamlString, type);
    }
}
