import java.util.Map;

public class ClassX {
    /**
     * Laadt configuratie vanuit een YAML-string.
     *
     * De functie controleert op expliciete gevaarlijke tags om objectinstantiatie te voorkomen.
     * Gebruikt {@link SafeConstructor} om alleen veilige, ingebouwde Java-typen toe te staan
     * (zoals String, Integer, List, Map, etc.) en voorkomt deserialisatie van willekeurige objecten.
     *
     * @param yamlString De YAML-string die de configuratie bevat.
     * @return Een {@link Map} die de geladen configuratie representeert.
     * @throws YAMLException Als er een fout optreedt tijdens het parsen of als de YAML gevaarlijke constructies bevat.
     */
    public Map<String, Object> loadSafeConfiguration(String yamlString) throws YAMLException {
        // Gebruik SafeConstructor om alleen veilige Java-typen toe te staan.
        // Dit voorkomt het laden van willekeurige klassen via YAML-tags zoals !!java.lang.Object.
        Yaml yaml = new Yaml(new SafeConstructor());

        // Laad de configuratie. De SafeConstructor zal controleren op gevaarlijke tags.
        // Het resultaat wordt meestal een Map<String, Object> voor algemene configuraties.
        Object loadedData = yaml.load(yamlString);

        if (loadedData instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> configMap = (Map<String, Object>) loadedData;
            return configMap;
        } else if (loadedData == null) {
            // Lege YAML-string kan null retourneren
            return java.util.Collections.emptyMap();
        } else {
            // Als de root van de YAML geen map is (bijv. een lijst of een enkele string),
            // kunnen we een uitzondering werpen of een lege map retourneren, afhankelijk van de vereisten.
            // Voor configuratie is een map het meest gangbaar.
            throw new YAMLException("De root van de YAML-configuratie is geen map.");
        }
    }
}
