    private boolean isBlacklisted(String domain) {
        if (domain == null || domain.trim().isEmpty()) {
            return false; // An empty or null domain cannot be blacklisted
        }
        // Normalize the domain to lowercase for case-insensitive comparison
        return MALICIOUS_DOMAINS.contains(domain.toLowerCase());
