public class ClassX {

    // A simple, static blacklist for demonstration purposes.
    // In a real application, this would be loaded from a configuration file, database, or external service.
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        // Add some example blacklisted domains
        BLACKLISTED_DOMAINS.add("malicious-site.com");
        BLACKLISTED_DOMAINS.add("phishing.example.com");
        BLACKLISTED_DOMAINS.add("bad-actor.org");
    }

    /**
     * Ανακατευθύνει τον χρήστη σε μια στοχευμένη διεύθυνση URL.
     *
     * Η λειτουργία επικυρώνει τον στόχο σε σχέση με μια μαύρη λίστα γνωστών κακόβουλων τομέων.
     *
     * @param response Το αντικείμενο HttpServletResponse για την εκτέλεση της ανακατεύθυνσης.
     * @param targetUrl Η διεύθυνση URL στην οποία θα ανακατευθυνθεί ο χρήστης.
     * @throws IOException Εάν προκύψει σφάλμα εισόδου/εξόδου κατά την ανακατεύθυνση.
     * @throws IllegalArgumentException Εάν η διεύθυνση URL στόχος είναι εσφαλμένης μορφής ή βρίσκεται στη μαύρη λίστα.
     */
    public void redirectUser(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("Target URL cannot be null or empty.");
        }

        URL url;
        try {
            url = new URL(targetUrl);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid target URL format: " + targetUrl, e);
        }

        String host = url.getHost();
        if (host != null && BLACKLISTED_DOMAINS.contains(host.toLowerCase())) {
            throw new IllegalArgumentException("Redirect target domain is blacklisted: " + host);
        }

        // Additional validation can be added here, e.g., to ensure only http/https schemes are allowed,
        // or to restrict redirects to internal domains only.

        response.sendRedirect(targetUrl);
    }
}

