import java.util.Set;

public class ClassX {

    // Een eenvoudige zwarte lijst voor demonstratiedoeleinden.
    // In een echte applicatie zou deze dynamisch geladen en beheerd worden.
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        BLACKLISTED_DOMAINS.add("malicious-site.com");
        BLACKLISTED_DOMAINS.add("phishing-domain.net");
        BLACKLISTED_DOMAINS.add("bad-actor.org");
        // Voeg hier meer kwaadaardige domeinen toe
    }

    /**
     * Stuur de gebruiker door naar een doel-URL.
     *
     * De functie valideert het doel tegen een zwarte lijst van bekende kwaadaardige domeinen.
     * Als het doel op de zwarte lijst staat, wordt de redirect geweigerd en wordt een foutstatus teruggestuurd.
     *
     * @param response De {@link HttpServletResponse} om de redirect uit te voeren.
     * @param targetUrl De URL waar de gebruiker naartoe gestuurd moet worden.
     * @throws IOException Als er een I/O-fout optreedt tijdens het versturen van de redirect of foutstatus.
     */
    public void redirectToTarget(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            // Log of handel een lege/null URL af
            System.err.println("Poging tot redirect met lege of null target URL.");
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Target URL mag niet leeg zijn.");
            return;
        }

        try {
            URL url = new URL(targetUrl);
            String host = url.getHost(); // Haal de host (domein) van de URL op

            if (host != null && BLACKLISTED_DOMAINS.contains(host.toLowerCase())) {
                // Log een poging om naar een domein op de zwarte lijst te redirecten
                System.err.println("Poging tot redirect naar domein op zwarte lijst geweigerd: " + host);
                // Stuur een foutstatus in plaats van te redirecten naar het kwaadaardige domein
                response.sendError(HttpServletResponse.SC_FORBIDDEN, "Redirect naar dit domein is niet toegestaan.");
                return;
            }

            // Als het domein niet op de zwarte lijst staat, voer de redirect uit
            response.sendRedirect(targetUrl);

        } catch (MalformedURLException e) {
            // Log of handel een ongeldig URL-formaat af
            System.err.println("Ongeldig URL-formaat voor target URL: " + targetUrl + " - " + e.getMessage());
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Ongeldig URL-formaat.");
        }
    }
}

