     * I-redirect ang gumagamit sa isang target na URL.
     *
     * Ang function ay nagva-validate ng target laban sa isang blacklist ng mga kilalang mapanlinlang na domain.
     *
     * @param response Ang HttpServletResponse object para sa pag-perform ng redirect.
     * @param targetUrl Ang URL kung saan ire-redirect ang gumagamit.
     * @throws IOException Kung may error sa I/O habang nagre-redirect.
     * @throws IllegalArgumentException Kung ang target URL ay nasa blacklist o hindi balido.
     */
    public void redirectToTarget(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("Ang target URL ay hindi maaaring walang laman.");
        }

        try {
            // Subukan na i-parse ang URL para makuha ang host
            URL url = new URL(targetUrl);
            String host = url.getHost();

            if (host != null && !host.isEmpty()) {
                // I-check kung ang host ay nasa blacklist (case-insensitive)
                for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
                    if (host.equalsIgnoreCase(blacklistedDomain) || host.endsWith("." + blacklistedDomain)) {
