                // Sa ngayon, ipagpatuloy ang redirect kung walang host (assuming it's relative and safe).
                // O kaya, itapon ang exception kung ang absolute URL lang ang pinapayagan.
                // Para sa seguridad, mas mainam na maging mahigpit.
                if (!targetUrl.startsWith("/")) { // Simple check for relative path
                    throw new IllegalArgumentException("Ang target URL ay hindi balido o walang host para sa security check: " + targetUrl);
