            URL url = new URL(urlString);
            String host = url.getHost();

            // Eliminar 'www.' si existe para una comparación más flexible
            if (host.startsWith("www.")) {
                host = host.substring(4);
            }

            return MALICIOUS_DOMAINS.contains(host);
