public class ClassX {

    /**
     * Uma lista negra de domínios maliciosos conhecidos para evitar redirecionamentos.
     * Esta lista é estática e pode ser inicializada com domínios de segurança conhecidos.
     */
    private static final Set<String> blacklistedDomains = new HashSet<>();

    static {
        // Inicializa a lista negra com domínios de exemplo.
        // Em um ambiente de produção, esta lista seria carregada de uma fonte segura
        // e atualizada regularmente.
        blacklistedDomains.add("malicious-site.com");
        blacklistedDomains.add("phishing-scam.net");
        blacklistedDomains.add("bad-actor-domain.org");
        // Adicionar outros domínios maliciosos conforme necessário
    }

    /**
     * Redireciona o usuário para uma URL de destino.
     *
     * A função valida o destino em relação a uma lista negra de domínios maliciosos conhecidos
     * antes de realizar o redirecionamento. Se a URL for considerada insegura ou inválida,
     * uma exceção será lançada.
     *
     * @param response O objeto {@link HttpServletResponse} usado para enviar o redirecionamento.
     * @param url A URL de destino para a qual o usuário será redirecionado.
     * @throws IOException Se ocorrer um erro de I/O durante o redirecionamento (por exemplo, o cliente já está comprometido).
     * @throws IllegalArgumentException Se a URL for nula, vazia, malformada ou pertencer a um domínio na lista negra.
     */
    public void redirect(HttpServletResponse response, String url) throws IOException {
        if (url == null || url.trim().isEmpty()) {
            throw new IllegalArgumentException("A URL de destino não pode ser nula ou vazia.");
        }

        URL parsedUrl;
        try {
            parsedUrl = new URL(url);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Formato de URL inválido: " + url, e);
        }

        // Extrai o host da URL para validação.
        // Nota: Para URLs relativas, getHost() pode retornar null.
        // A validação da lista negra é primariamente para hosts absolutos.
        String host = parsedUrl.getHost();
        if (host != null && !host.isEmpty()) {
            if (blacklistedDomains.contains(host.toLowerCase())) { // Comparação case-insensitive
                throw new IllegalArgumentException("Redirecionamento para domínio na lista negra não permitido: " + host);
            }
        }

        // Se a validação passar, executa o redirecionamento.
        response.sendRedirect(url);
    }
}
