     *
     * @param xmlContent La cadena que contiene el contenido XML a analizar.
     * @return El objeto Document W3C que representa el XML analizado.
     * @throws ParserConfigurationException Si no se puede crear un DocumentBuilder con la configuración especificada.
     * @throws SAXException Si ocurre un error de análisis SAX.
     * @throws IOException Si ocurre un error de E/S al leer el contenido XML.
     */
    public Document parseXmlDocument(String xmlContent)
            throws ParserConfigurationException, SAXException, IOException {

        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // Configurar el DocumentBuilderFactory para prevenir ataques XXE.
        // Deshabilitar la resolución de entidades externas y DOCTYPE.
        try {
            // Activar el procesamiento seguro, que debería deshabilitar la mayoría de las características peligrosas.
            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Deshabilitar explícitamente las declaraciones DOCTYPE.
            // Esto es crucial para prevenir XXE al evitar que el parser procese DTDs.
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // Deshabilitar la resolución de entidades generales externas.
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);

            // Deshabilitar la resolución de entidades de parámetros externas.
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

            // Deshabilitar la expansión de referencias de entidad.
            dbf.setExpandEntityReferences(false);

            // Deshabilitar el procesamiento de XInclude.
            dbf.setXIncludeAware(false);

        } catch (ParserConfigurationException e) {
            // Manejar la excepción si alguna de las características no es compatible
            // o si ocurre un error de configuración.
            // En un entorno de producción, esto podría ser un registro o una re-lanzamiento.
            System.err.println("Error al configurar DocumentBuilderFactory para la prevención de XXE: " + e.getMessage());
            throw e; // Re-lanzar para indicar que la configuración falló
        }

        DocumentBuilder db = dbf.newDocumentBuilder();

        // Configurar el manejador de errores para el DocumentBuilder (opcional pero recomendado)
        // db.setErrorHandler(new DefaultHandler() {
        //     @Override
        //     public void error(SAXParseException e) throws SAXException {
        //         throw e; // Lanza errores de análisis
        //     }
        // });

        return db.parse(new ByteArrayInputStream(xmlContent.getBytes()));
    }
}
