import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import javax.xml.XMLConstants;

public class ClassX {
    /**
     * Analiza un documento XML.
     * 
     * La función verifica la presencia de declaraciones 'DOCTYPE' para prevenir XXE.
     *
     * @param xmlStream Un {@link ByteArrayInputStream} que contiene el documento XML a analizar.
     * @return Un objeto {@link Document} que representa el documento XML analizado.
     * @throws ParserConfigurationException Si ocurre un problema con la configuración del analizador.
     * @throws SAXException Si ocurre un error de análisis SAX.
     * @throws IOException Si ocurre un error de E/S.
     */
    public Document parseXmlDocument(ByteArrayInputStream xmlStream) 
            throws ParserConfigurationException, SAXException, IOException {

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Configuración para prevenir ataques XXE
        // 1. Habilita el procesamiento seguro para características estándar
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // 2. Deshabilita las declaraciones DOCTYPE completamente (específico de Xerces, pero ampliamente compatible)
        // Esto es crucial para prevenir la carga de DTDs externas que podrían contener entidades maliciosas.
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // 3. Deshabilita el procesamiento de entidades generales externas
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);

        // 4. Deshabilita el procesamiento de entidades de parámetros externas
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // 5. Deshabilita la expansión de referencias de entidad
        factory.setExpandEntityReferences(false);

        // 6. Deshabilita XInclude
        factory.setXIncludeAware(false);

        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(xmlStream);

        // Normaliza el documento XML, lo que a veces ayuda a eliminar nodos vacíos
        // y consolidar nodos de texto adyacentes.
        document.normalize();

        return document;
    }
}
