import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Analiza un documento XML.
     * 
     * La función verifica la presencia de declaraciones 'DOCTYPE' para prevenir XXE.
     *
     * @param xmlString La cadena XML a analizar.
     * @return Un objeto Document que representa el XML analizado.
     * @throws ParserConfigurationException Si ocurre un error al configurar el analizador XML.
     * @throws SAXException Si ocurre un error durante el análisis del XML.
     * @throws IOException Si ocurre un error de E/S al leer el XML.
     */
    public Document parseXml(String xmlString) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Deshabilitar el procesamiento de DOCTYPE para prevenir XXE
        // Esto previene la carga de DTDs externas y la expansión de entidades
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // Deshabilitar la resolución de entidades externas generales y de parámetros
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // Deshabilitar XInclude para prevenir la inclusión de contenido externo
        factory.setXIncludeAware(false);

        // Deshabilitar la expansión de referencias de entidad
        factory.setExpandEntityReferences(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Parsear el XML desde un ByteArrayInputStream
        // Se utiliza StandardCharsets.UTF_8 para asegurar la codificación correcta
        try (ByteArrayInputStream input = new ByteArrayInputStream(xmlString.getBytes(StandardCharsets.UTF_8))) {
            return builder.parse(input);
        }
    }
