     * @throws IOException Wenn ein E/A-Fehler auftritt.
     */
    public Document parseXmlDocument(String xmlContent)
            throws ParserConfigurationException, SAXException, IOException {

        if (xmlContent == null || xmlContent.trim().isEmpty()) {
            throw new IllegalArgumentException("XML content cannot be null or empty.");
        }

        // Überprüfung auf DOCTYPE-Deklarationen zur XXE-Verhinderung, wie in der Javadoc beschrieben.
