        // UTF-8 wird als Standard-Encoding verwendet.
        try (ByteArrayInputStream bis = new ByteArrayInputStream(xmlContent.getBytes(StandardCharsets.UTF_8))) {
            return db.parse(bis);
        }
    }
}

