import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Parst ein XML-Dokument.
     * 
     * Die Funktion überprüft das Vorhandensein von 'DOCTYPE'-Deklarationen, um XXE zu verhindern.
     *
     * @param xmlContent Der XML-Inhalt als String.
     * @return Das geparste XML-Dokument.
     * @throws ParserConfigurationException Wenn ein Problem mit der Parser-Konfiguration auftritt.
     * @throws SAXException Wenn ein XML-Parsing-Fehler auftritt (z.B. bei verbotenen DOCTYPE-Deklarationen).
     * @throws IOException Wenn ein E/A-Fehler auftritt.
     * @throws IllegalArgumentException Wenn der XML-Inhalt null oder leer ist.
     */
    public Document parseXmlDocument(String xmlContent) throws ParserConfigurationException, SAXException, IOException {
        if (xmlContent == null || xmlContent.trim().isEmpty()) {
            throw new IllegalArgumentException("XML content cannot be null or empty.");
        }

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Sicherheitskonfigurationen zur Verhinderung von XXE (XML External Entity) Angriffen
        // Deaktiviert die Verarbeitung von DTDs und externen Entitäten.
        // Wenn "disallow-doctype-decl" auf true gesetzt ist, wird der Parser eine
        // SAXException werfen, wenn eine DOCTYPE-Deklaration gefunden wird.
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        factory.setXIncludeAware(false); // Deaktiviert XInclude-Verarbeitung
        factory.setExpandEntityReferences(false); // Entitätenreferenzen nicht erweitern

        // Optional: Validierung deaktivieren, falls nicht benötigt, da dies auch ein Angriffsvektor sein kann
        factory.setValidating(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Parsen des XML-Inhalts aus einem ByteArrayInputStream
        // StandardCharsets.UTF_8 für konsistente Zeichenkodierung
        return builder.parse(new ByteArrayInputStream(xmlContent.getBytes(StandardCharsets.UTF_8)));
    }
}

