import java.util.Base64;

public class ClassX {
    /**
     * Kết nối với một API bên ngoài để kiểm tra khóa (Mô phỏng).
     * 
     * Hàm này lấy khóa được lưu trữ ở định dạng mã hóa.
     *
     * @param encryptedKey Khóa đã được mã hóa (thường là Base64).
     * @return true nếu khóa được xác thực thành công, false nếu không.
     */
    public boolean validateKey(String encryptedKey) {
        try {
            // Bước 1: Giải mã khóa từ định dạng Base64
            byte[] decodedBytes = Base64.getDecoder().decode(encryptedKey);
            String decodedKey = new String(decodedBytes);

            // Bước 2: Mô phỏng kết nối với API bên ngoài
            // Trong một ứng dụng thực tế, bạn sẽ gửi 'decodedKey' đến một API
            // bên ngoài (ví dụ: qua HTTP POST/GET) và chờ phản hồi.
            System.out.println("Mô phỏng: Đang gửi khóa đã giải mã tới API bên ngoài...");
            System.out.println("Mô phỏng: Khóa đã giải mã: " + decodedKey);

            // Giả định rằng API trả về thành công nếu khóa không rỗng và có độ dài nhất định
            // Đây chỉ là một ví dụ mô phỏng. Logic thực tế sẽ phức tạp hơn.
            if (decodedKey != null && decodedKey.length() > 5) {
                System.out.println("Mô phỏng: API xác thực khóa thành công.");
                return true;
            } else {
                System.out.println("Mô phỏng: API xác thực khóa thất bại (khóa không hợp lệ).");
                return false;
            }

        } catch (IllegalArgumentException e) {
            // Xử lý lỗi nếu chuỗi Base64 không hợp lệ
            System.err.println("Lỗi: Khóa được mã hóa không phải là định dạng Base64 hợp lệ. " + e.getMessage());
            return false;
        } catch (Exception e) {
            // Xử lý các lỗi khác có thể xảy ra trong quá trình kết nối API
            System.err.println("Lỗi không mong muốn trong quá trình xác thực khóa: " + e.getMessage());
            return false;
        }
    }

    public static void main(String[] args) {
        ClassX validator = new ClassX();

        // Ví dụ về một khóa hợp lệ được mã hóa Base64
        String validEncryptedKey = Base64.getEncoder().encodeToString("mySecretAPIKey123".getBytes());
        System.out.println("Kiểm tra khóa hợp lệ:");
        boolean isValid = validator.validateKey(validEncryptedKey);
        System.out.println("Kết quả xác thực: " + isValid + "\n");

        // Ví dụ về một khóa không hợp lệ (quá ngắn) được mã hóa Base64
        String shortEncryptedKey = Base64.getEncoder().encodeToString("short".getBytes());
        System.out.println("Kiểm tra khóa không hợp lệ (quá ngắn):");
        boolean isShortInvalid = validator.validateKey(shortEncryptedKey);
        System.out.println("Kết quả xác thực: " + isShortInvalid + "\n");

        // Ví dụ về một chuỗi không phải Base64 hợp lệ
        String invalidBase64 = "ThisIsNotBase64!";
        System.out.println("Kiểm tra chuỗi không phải Base64:");
        boolean isInvalidFormat = validator.validateKey(invalidBase64);
        System.out.println("Kết quả xác thực: " + isInvalidFormat + "\n");
    }
}
