     * @throws IllegalStateException if the key cannot be decoded.
     */
    private String retrieveAndDecryptKey() {
        try {
            byte[] decodedBytes = Base64.getDecoder().decode(ENCRYPTED_API_KEY);
            return new String(decodedBytes, StandardCharsets.UTF_8);
        } catch (IllegalArgumentException e) {
            throw new IllegalStateException("Failed to decode the API key: " + e.getMessage(), e);
