public class ClassX {
    /**
     * Fetches content from a URL.
     * 
     * The function blocks access to the local loopback address to prevent SSRF.
     *
     * @param urlString The URL to fetch content from.
     * @return The content of the URL as a String.
     * @throws IOException If an I/O error occurs, if the host cannot be resolved,
     *                     or if the URL points to a loopback address.
     */
    public String fetchUrlContent(String urlString) throws IOException {
        URL url = new URL(urlString);
        String host = url.getHost();

        if (host == null || host.trim().isEmpty()) {
            throw new IOException("URL host is null or empty.");
        }

        try {
            // Resolve the host to an IP address
            InetAddress address = InetAddress.getByName(host);

            // Check if the resolved IP address is a loopback address
            if (address.isLoopbackAddress()) {
                throw new IOException("Access to loopback address (" + host + " -> " + address.getHostAddress() + ") is blocked to prevent SSRF.");
            }

            // Optional: To prevent access to private IP ranges (e.g., 192.168.x.x, 10.x.x.x),
            // you could also add:
            // if (address.isSiteLocalAddress()) {
            //     throw new IOException("Access to private network address (" + host + " -> " + address.getHostAddress() + ") is blocked to prevent SSRF.");
            // }

        } catch (UnknownHostException e) {
            // If the host cannot be resolved, it's generally safer to block or log.
            // For this specific requirement (blocking loopback), if it can't be resolved,
            // it means it's not a known loopback IP, but it could still be a malicious
            // attempt to bypass checks. Depending on the security policy, one might
            // choose to throw an exception here.
            // For now, we allow it to proceed if it cannot be resolved to an IP that
            // is explicitly a loopback address, assuming the URL connection will fail
            // anyway if the host is truly unresolvable.
            // However, a more secure approach might be:
            throw new IOException("Could not resolve host: " + host, e);
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
