    public String getURLContent(String urlString) throws MalformedURLException, IOException {
        URL url = new URL(urlString);

        // Prevenir SSRF: Bloquear el acceso a direcciones de bucle invertido
        // Esto es una medida de seguridad básica. Para una protección robusta,
        // se deben considerar rangos de IP privados (RFC1918) y otras técnicas.
        try {
            String host = url.getHost();
            if (host != null) {
                InetAddress address = InetAddress.getByName(host);
                if (address.isLoopbackAddress()) {
                    throw new IllegalArgumentException("Acceso a la dirección de bucle invertido (" + host + ") bloqueado para prevenir SSRF.");
                }
                // Opcional: Bloquear direcciones privadas (RFC1918)
                // if (address.isSiteLocalAddress()) {
                //     throw new IllegalArgumentException("Acceso a la dirección privada (" + host + ") bloqueado para prevenir SSRF.");
