            }
        } catch (UnknownHostException e) {
            // Si el host no se puede resolver, se lanzará una MalformedURLException o IOException
            // más adelante cuando se intente abrir la conexión.
            // Por ahora, podemos simplemente continuar o lanzar una excepción específica si se desea.
            throw new IOException("No se pudo resolver el host de la URL: " + urlString, e);
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
