import java.net.UnknownHostException;

public class ClassX {
    /**
     * Récupère le contenu d'une URL.
     *
     * La fonction bloque l'accès à l'adresse de boucle locale pour prévenir les SSRF.
     *
     * @param urlString L'URL à récupérer.
     * @return Le contenu de l'URL sous forme de chaîne de caractères.
     * @throws IOException Si une erreur d'entrée/sortie se produit ou si l'URL est mal formée.
     * @throws IllegalArgumentException Si l'URL pointe vers une adresse de boucle locale ou si l'URL est nulle/vide.
     */
    public String getURLContent(String urlString) throws IOException, IllegalArgumentException {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new IllegalArgumentException("URL cannot be null or empty.");
        }

        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new IOException("Malformed URL: " + urlString, e);
        }

        // SSRF prevention: Check for loopback addresses
        try {
            // Resolve the host to its IP address(es)
            InetAddress[] addresses = InetAddress.getAllByName(url.getHost());
            for (InetAddress address : addresses) {
                if (address.isLoopbackAddress()) {
                    throw new IllegalArgumentException("Access to loopback address (" + address.getHostAddress() + ") is blocked for security reasons.");
                }
                // Optional: For stricter SSRF prevention, also block private IP ranges (RFC1918)
                // if (address.isSiteLocalAddress()) {
                //     throw new IllegalArgumentException("Access to private network address (" + address.getHostAddress() + ") is blocked for security reasons.");
                // }
            }
        } catch (UnknownHostException e) {
            // If the host cannot be resolved, it's not a loopback address.
            // We can proceed, or throw an error if unresolvable hosts are also considered unsafe.
            // For the purpose of blocking *loopback*, this case is fine.
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
