            // If the host cannot be resolved, it's not a loopback address (or any other address),
            // but the connection will fail later anyway. We can let it proceed to fail naturally.
            // Or, we could throw an exception here if we want to fail early for unknown hosts.
            // For now, let's just log and proceed, allowing the URL connection to handle the actual failure.
            System.err.println("Warning: Could not resolve host '" + host + "'. " + e.getMessage());
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }

