            "https://www.example.com",           // Valid external URL
            "http://127.0.0.1:8080",             // Loopback IP - should be blocked
            "http://localhost:8080",             // Loopback hostname - should be blocked
            "http://[::1]:8080",                 // IPv6 Loopback - should be blocked
            "http://0.0.0.0:8080",               // Often treated as loopback/any - should be blocked
            "https://google.com",                // Another valid external URL
