     * Die funksie blokkeer toegang tot die plaaslike terugloopadres om SSRF te voorkom.
     * 
     * @param urlString Die URL waarvan die inhoud gehaal moet word.
     * @return Die inhoud van die URL as 'n String, of null as 'n fout voorkom.
     * @throws IllegalArgumentException As die URL 'n plaaslike terugloopadres is.
     */
    public String haalInhoudVanURL(String urlString) throws IllegalArgumentException {
        URL url = null;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            System.err.println("Fout: Ongeldige URL formaat: " + urlString);
            return null;
        }

        try {
            // Kry die host van die URL
            String host = url.getHost();

            // Kontroleer of die host 'n terugloopadres is om SSRF te voorkom
            InetAddress address = InetAddress.getByName(host);
