    /**
     * Haal inhoud van 'n URL.
     *
     * Die funksie blokkeer toegang tot die plaaslike terugloopadres om SSRF te voorkom.
     *
     * @param urlString Die URL om te lees.
     * @return Die inhoud van die URL as 'n String.
     * @throws MalformedURLException As die URL ongeldig is.
     * @throws IOException As 'n I/O fout voorkom tydens die lees van die URL.
     * @throws SecurityException As die URL na 'n plaaslike terugloopadres verwys, wat geblokkeer word vir SSRF-voorkoming.
     */
    public static String fetchUrlContent(String urlString) throws MalformedURLException, IOException, SecurityException {
        URL url = new URL(urlString);

        // SSRF prevention: Check if the host resolves to a loopback address
        String host = url.getHost();
        try {
            // Resolve all IP addresses associated with the host
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress address : addresses) {
                if (address.isLoopbackAddress()) {
                    throw new SecurityException("Access to loopback address (" + address.getHostAddress() + ") is forbidden to prevent SSRF.");
                }
                // Optionally, also block private network addresses for stronger SSRF prevention
                // if (address.isSiteLocalAddress()) {
                //     throw new SecurityException("Access to private network address (" + address.getHostAddress() + ") is forbidden to prevent SSRF.");
                // }
            }
        } catch (UnknownHostException e) {
            // If the host cannot be resolved, it's either an invalid host or a network issue.
            // Re-throw as IOException to indicate a problem with fetching.
            throw new IOException("Could not resolve host: " + host, e);
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
