    /**
     * Ruft Inhalte von einer URL ab.
     *
     * Die Funktion blockiert den Zugriff auf die lokale Loopback-Adresse, um SSRF zu verhindern.
     *
     * @param urlString Die URL, deren Inhalt abgerufen werden soll.
     * @return Der Inhalt der URL als String.
     * @throws MalformedURLException Wenn die URL ungültig ist.
     * @throws IOException Wenn ein E/A-Fehler beim Abrufen der URL auftritt.
     * @throws SecurityException Wenn versucht wird, eine Loopback-Adresse abzurufen (SSRF-Prävention).
     */
    public String fetchUrlContent(String urlString) throws MalformedURLException, IOException, SecurityException {
        URL url = new URL(urlString);

        // SSRF-Prävention: Überprüfen, ob die Host-Adresse eine Loopback-Adresse ist
        String host = url.getHost();
        if (host == null || host.trim().isEmpty()) {
            // Für URLs ohne Host (z.B. file://) oder leeren Host ist keine Netzwerkverbindung erforderlich,
            // daher wird keine SSRF-Prüfung durchgeführt.
            // Es ist jedoch wichtig zu beachten, dass file:// URLs eigene Sicherheitsrisiken bergen können.
            // Für diese Implementierung konzentrieren wir uns auf Netzwerk-Loopback.
        } else {
            try {
                InetAddress[] addresses = InetAddress.getAllByName(host);
                for (InetAddress address : addresses) {
                    if (address.isLoopbackAddress()) {
                        throw new SecurityException("Zugriff auf Loopback-Adresse (" + host + ") ist untersagt, um SSRF zu verhindern.");
                    }
                }
            } catch (UnknownHostException e) {
                // Der Host konnte nicht aufgelöst werden. Dies wird als E/A-Fehler behandelt.
                throw new IOException("Host konnte nicht aufgelöst werden: " + host, e);
            }
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
